import type { Lesson } from './types.ts';
import { guideLesson } from './define.ts';

const s = (title:string,body:string,code?:string) => ({title,body,...(code ? {code} : {})});
const q = (question:string,options:string[],answer:number,explanation:string) => ({question,options,answer,explanation});
function a(slug:string,title:string,description:string,prerequisites:string[],objectives:string[],sections:Lesson['sections'],quiz:Lesson['quiz'],minutes=50):Lesson {
  return guideLesson('adv',slug,{title,description,prerequisites,objectives,sections,quiz,minutes,optional:true});
}

export const advancedLessons:Lesson[] = [
  a('springboards','Fronteras de dominancia y máximos de sufijo','Descarta estados que jamás podrán mejorar una respuesta y conserva solamente una frontera útil.',
    ['usaco-gold-intro-sorted-sets','usaco-plat-range-sweep'],['Reconocer dominancia entre estados','Mantener una frontera con un mapa ordenado'],[
      s("Cuándo una oferta deja de servir","Una oferta de transporte tiene alcance y ahorro. Quieres el mayor ahorro entre las que lleguen al menos hasta x. Si tienes (4,7) y (6,9), puedes descartar la primera: siempre que sirva, la segunda también sirve y ahorra más. Se dice que la segunda domina a la primera.\n\nAquí solo agregas ofertas. Si permitieras borrar la dominante, tendrías que recuperar información descartada."),
      s("Conservar la frontera en un mapa","Ordena por alcance los pares no dominados. Sus ahorros deben disminuir estrictamente. Para consultar x, lower_bound(x) encuentra la primera oferta permitida; su ahorro es el mayor del sufijo.\n\nAntes de insertar (a,b), revisa ese sucesor. Si ahorra al menos b, descarta la nueva oferta. Si no, inserta o mejora la clave a y borra los predecesores cuyo ahorro sea menor o igual a b."),
      s("Una secuencia de inserciones","Con (2,9), (5,6), (8,3), la consulta x=4 devuelve seis. Agrega (6,8): desaparece (5,6), pero (2,9) sigue siendo útil para alcances pequeños. Ahora x=4 devuelve ocho y x=7 devuelve tres.\n\nEl programa sigue esa secuencia. Usa optional para distinguir una consulta sin oferta de una oferta cuyo ahorro sea cero o negativo.", String.raw`#include <iostream>
#include <map>
#include <iterator>
#include <optional>
using namespace std;
map<int,long long> frontier;
void insert_offer(int x,long long y){
  auto it=frontier.lower_bound(x);
  if(it!=frontier.end() && it->second>=y) return;
  if(it!=frontier.end() && it->first==x) it=frontier.erase(it);
  it=frontier.emplace_hint(it,x,y);
  while(it!=frontier.begin()){
    auto before=prev(it);
    if(before->second>y) break;
    frontier.erase(before);
  }
}
optional<long long> query(int x){
  auto it=frontier.lower_bound(x);
  if(it==frontier.end()) return nullopt;
  return it->second;
}
int main(){
  insert_offer(2,9); insert_offer(5,6); insert_offer(8,3);
  cout<<*query(4)<<'\n';
  insert_offer(6,8);
  cout<<*query(4)<<' '<<*query(7)<<'\n';
}`),
      s("Costo amortizado","Una inserción puede borrar muchos pares, pero cada par desaparece como mucho una vez. N inserciones y Q consultas cuestan O((N+Q) log N) en total y O(N) memoria; una operación aislada puede ser costosa.\n\nPrueba claves repetidas y ahorros negativos. Si modelas trampolines como eventos de un barrido, define qué ocurre primero cuando un final coincide con otro inicio.")
    ],q('Después de insertar (3,5), (7,2) y (8,6), ¿qué pares quedan?', ['Los tres','Solo (8,6)','(3,5) y (8,6)'],1,'(8,6) tiene alcance y ahorro al menos tan grandes como ambos pares anteriores, por lo que los domina.')),

  a('wavelet','Wavelet tree: valores dentro de intervalos','Responde cuántos valores pequeños hay en un intervalo y encuentra su k-ésimo elemento.',
    ['usaco-plat-segtree-ext','usaco-silver-prefix-sums'],['Mapear intervalos entre niveles','Resolver selección por rango de valores'],[
      s("Dividir por valores","Un wavelet tree separa los valores en dos mitades, conservando el orden relativo dentro de cada una. Esa partición estable permite saber dónde quedó un intervalo original al pasar a un hijo.\n\nLa división principal ocurre sobre los valores. Las posiciones se trasladan con conteos de prefijo. Si los valores son grandes, comprime sus coordenadas antes de construir el árbol."),
      s("Trasladar un intervalo","Usa [l,r) y define pref[i] como cuántas de las primeras i posiciones fueron al hijo izquierdo. Allí el intervalo queda [pref[l],pref[r]); a la derecha, [l−pref[l],r−pref[r]).\n\nLa izquierda contiene pref[r]−pref[l] elementos. Para buscar el k-ésimo menor, contando desde uno, baja allí si esa cantidad alcanza k. Si no, réstala de k y continúa a la derecha."),
      s("Encontrar el segundo menor","En [4,1,3,2], separa los valores [1,2] de [3,4]. El prefijo izquierdo es [0,0,1,1,2]. Quieres el segundo menor de A[1,4)=[1,3,2].\n\nSu intervalo izquierdo es [pref[1],pref[4])=[0,2): contiene dos valores, así que bajas con k=2. Al separar uno y dos, solo hay un uno. El segundo menor es dos, sin ordenar el subarreglo de la consulta."),
      s("Costo y actualizaciones","Con σ valores comprimidos, construir cuesta O(n log σ); cada selección o conteo, O(log σ). Una versión con arreglos de prefijos ocupa O(n log σ) enteros. Los bitvectors con rank pueden reducir ese espacio.\n\nEsta estructura es estática: cambiar un valor puede alterar varias particiones. Comprueba consultas pequeñas copiando y ordenando el subarreglo. Incluye repetidos y revisa 1≤k≤r−l.")
    ],q('¿Cuántos elementos de [l,r) van al hijo izquierdo?', ['pref[r]−pref[l]','pref[r]−pref[l]+1','r−l−pref[r]'],0,'pref cuenta posiciones anteriores al extremo; la resta es exactamente el conteo del intervalo semiabierto.')),

  a('count-min','Contar mínimos y medir cobertura','Combina mínimo y multiplicidad para resolver consultas y áreas de uniones de rectángulos.',
    ['usaco-plat-rurq','usaco-plat-sweep-line'],['Construir un resumen asociativo con mínimo y conteo','Interpretar cobertura cero durante un barrido'],[
      s("Mínimo y cantidad","Si además del mínimo quieres saber cuántas veces aparece, guarda (mínimo,cantidad). Al unir intervalos, conserva el menor mínimo; si empatan, suma las cantidades. Un intervalo vacío aporta (infinito,0).\n\nLa operación es asociativa porque siempre describe el intervalo unido. Puedes usarla en un árbol de segmentos sin que el resultado dependa de cómo agrupes las combinaciones."),
      s("Sumar a un intervalo","En [3,1,1,4], el resumen es (1,2). Suma dos a [1,3): obtienes [3,3,3,4] y el resumen (3,3).\n\nDentro de un nodo completamente cubierto, una suma uniforme cambia el mínimo y conserva su cantidad. Por eso admite propagación diferida. Una asignación es distinta: todos sus valores pasan a ser iguales y la cantidad se vuelve el tamaño del intervalo."),
      s("Medir longitud cubierta","En un barrido de rectángulos, una hoja representa [y[i],y[i+1]) y guarda su longitud. El mínimo mide cobertura; la cantidad mide longitud con esa cobertura mínima.\n\nSi el mínimo global es cero, resta su longitud de la longitud total para obtener la cubierta. Si es positivo, toda está cubierta. Multiplica por la distancia hasta el siguiente evento x. Agrupa eventos con el mismo x antes de avanzar.", String.raw`#include <iostream>
#include <vector>
#include <limits>
using namespace std;
struct Node {long long minimum,count;};
Node merge(Node a,Node b){
  if(a.minimum<b.minimum) return a;
  if(b.minimum<a.minimum) return b;
  return {a.minimum,a.count+b.count};
}
int main(){
  vector<long long> a={3,1,1,4};
  Node answer={numeric_limits<long long>::max(),0};
  for(long long x:a) answer=merge(answer,{x,1});
  cout<<answer.minimum<<' '<<answer.count<<'\n';
}`),
      s("Costo y casos de prueba","Con propagación diferida, cada consulta o suma de intervalo cuesta O(log n); el árbol ocupa O(n). La unión de R rectángulos cuesta O(R log R), incluyendo eventos y compresión. El programa anterior muestra solo la combinación de resúmenes.\n\nPrueba rectángulos anidados, bordes coincidentes y grandes huecos entre coordenadas. Para medir área necesitas las diferencias de coordenadas, no cuántos índices comprimidos hay.")
    ],q('Una hoja representa [2,8), sin cobertura. ¿Qué cantidad almacena?', ['1','6','8'],1,'En geometría se mide longitud: 8−2=6, no el número de índices comprimidos.')),

  a('segtree-beats','Segment tree beats','Acelera actualizaciones chmin con información sobre el máximo y un análisis amortizado.',
    ['usaco-plat-rurq'],['Decidir cuándo una actualización puede detenerse en un nodo','Distinguir costo amortizado de costo individual'],[
      s("Qué falta para aplicar chmin","chmin(l,r,x) cambia cada a del intervalo por min(a,x). Con solo suma y máximo no sabes cuánto baja la suma: pueden cambiar uno o varios valores.\n\nSegment tree beats añade el segundo máximo distinto y cuántas veces aparece el máximo. Si solo cambia esa clase de valores, puedes actualizar el nodo directamente. Si cambian más clases, bajas a sus hijos."),
      s("Cuándo puedes detenerte en un nodo","Llama M al máximo, S al segundo máximo distinto y c a la cantidad de máximos. Si x≥M, no cambia nada. Si S<x<M, los c máximos bajan a x: suma += (x−M)·c y M=x.\n\nSi x≤S, baja a los hijos. En x=S se juntarían dos clases y no conoces la nueva multiplicidad; por eso la desigualdad debe ser estricta."),
      s("Aplicar dos umbrales","En [9,9,4,1], la suma es 23, M=9, S=4 y c=2. Con x=6, solo bajan los dos nueves: sumas (6−9)·2=−6 y obtienes 17.\n\nDespués, x=3 también afecta al cuatro, así que debes bajar. El resultado es [3,3,3,1], suma diez. Al propagar, el máximo del padre limita los máximos de sus hijos; aplica primero los pendientes compatibles y después reconstruye los resúmenes."),
      s("Qué cota puedes usar","Para chmin y consultas de suma, sin sumas arbitrarias por rango, el análisis amortizado da O((n+q) log n) total y O(n) memoria. Una operación puede visitar muchos nodos. Agregar chmax o sumas requiere nuevos invariantes y otro análisis.\n\nCompara con un arreglo directo. Incluye valores iguales, negativos y x exactamente igual al segundo máximo. Usa un centinela suficientemente pequeño y evita multiplicar por él.")
    ],q('En [8,8,5,2], ¿qué umbral permite actualizar solo la clase máxima?', ['x=5','x=6','x=4'],1,'El segundo máximo es 5; se requiere 5<x<8. Con x=6 cambian solo los dos ochos.')),

  a('persistent','Estructuras persistentes: consultar el pasado','Conserva versiones de un árbol compartiendo las partes que no cambiaron.',
    ['usaco-plat-segtree-ext','usaco-plat-sparse-segtree'],['Construir versiones mediante copia de caminos','Restar versiones de frecuencias para seleccionar por rango'],[
      s("Conservar versiones anteriores","Piensa en consultar un documento antes y después de editarlo. Una estructura persistente conserva esos estados. En un árbol de segmentos, cambiar una posición solo afecta a su hoja y sus ancestros.\n\nCopia esos nodos y crea una raíz nueva. Los hijos que no cambian siguen apuntando a los nodos anteriores. Nunca modifiques un nodo compartido: eso alteraría también la versión antigua."),
      s("Consultar dos versiones","Parte de [2,0,5,1], cuya raíz r0 suma ocho. Al asignar A[1]=7, crea r1 con suma quince. Ambas raíces comparten el subárbol de [5,1]. La consulta [0,2) vale dos en r0 y nueve en r1.\n\nSi puedes actualizar cualquier versión, tienes persistencia completa. Si solo actualizas la más reciente, es parcial. La copia de nodos permite conservar las consultas antiguas en ambos casos."),
      s("Restar frecuencias de prefijos","Construye r[i] con las frecuencias de los primeros i valores. Para A[l,r), resta los conteos de r[l] a los de r[r]. En [3,1,3,2], la consulta [1,4) representa {1,3,2}.\n\nPara buscar el segundo menor, calcula el conteo izquierdo entre ambas raíces. Si alcanza k, baja a la izquierda; si no, réstalo y baja a la derecha. La resta funciona porque los resúmenes son sumas de frecuencias."),
      s("Espacio de las versiones","Un árbol inicial completo ocupa O(n). Cada cambio copia O(log n) nodos; con q cambios, la memoria es O(n+q log n), y cada consulta cuesta O(log n). Para selección por valores, la altura depende del universo comprimido σ.\n\nUsa índices en el vector de nodos: push_back puede invalidar referencias. Comprueba que crear versiones nuevas no cambie consultas antiguas. No puedes restar máximos como si fueran frecuencias.")
    ],q('¿Qué nodos se copian para una actualización puntual?', ['Todos los nodos','Solo la hoja','La hoja y el camino hasta la raíz'],2,'Solo esos O(log n) resúmenes cambian; los otros subárboles pueden compartirse sin mutarlos.')),

  a('treaps','Treaps y secuencias implícitas','Combina el orden de un árbol de búsqueda con prioridades aleatorias para partir y unir secuencias.',
    ['usaco-gold-intro-sorted-sets','usaco-plat-rurq'],['Mantener los invariantes de clave y prioridad','Implementar conceptualmente split, merge e inversión'],[
      s("Clave y prioridad","Un treap conserva dos órdenes: árbol de búsqueda por clave y montículo por prioridad aleatoria. Las prioridades sirven para equilibrarlo. Si son independientes y distintas, su forma equivale a insertar las claves en un orden aleatorio y su altura esperada es O(log n).\n\nPuedes desempatar prioridades iguales con un identificador. La cota es esperada: en el peor caso, el árbol todavía puede formar una cadena."),
      s("Separar y volver a unir","split(T,k) separa las claves menores que k del resto. Compara con la raíz, divide el hijo correspondiente y recalcula tamaños al volver.\n\nmerge(A,B) exige que todas las claves de A precedan a las de B. Elige la raíz por prioridad y une su hijo interior recursivamente. No ordena dos árboles arbitrarios. Con unas pocas llamadas a split y merge puedes insertar o borrar elementos."),
      s("Usar posiciones sin renumerar","En un treap implícito, el tamaño del hijo izquierdo determina la posición; no guardas claves que debas renumerar. Para invertir [1,4) en [a,b,c,d,e], separa [a], [b,c,d], [e].\n\nInvierte el bloque central con una bandera e intercambia sus hijos. Al unir, obtienes [a,d,c,b,e]. Antes de bajar, propaga la bandera. Después de cambiar enlaces, recalcula tamaños y sumas."),
      s("Costo y comprobación","Cada split o merge cuesta O(log n) esperado y el árbol ocupa O(n). Una operación con un número constante de esas llamadas conserva la cota.\n\nImplementa primero inserción y consulta por posición; después, inversión y sumas. Compara con vector en secuencias pequeñas. Revisa push antes de bajar, pull después de reconectar y la convención [l,r). No reutilices un nodo eliminado si otra parte aún lo referencia.")
    ],q('¿Qué condición necesita merge(A,B) en un treap de claves?', ['Todas las claves de A preceden a las de B','A y B tienen el mismo tamaño','Las prioridades de A son menores'],0,'La prioridad elige la raíz, pero el orden de búsqueda solo se preserva si las claves de A están antes que las de B.')),

  a('line-container','Contenedores dinámicos de rectas','Consulta mínimos de funciones lineales sin exigir que lleguen ordenadas por pendiente.',
    ['usaco-plat-convex-hull-trick','usaco-plat-sparse-segtree'],['Entender el invariante de Li Chao','Elegir entre envolvente ordenada y árbol sobre coordenadas'],[
      s("Una transición como consulta de rectas","En dp[i]=min(j<i){dp[j]+b[j]·a[i]}, cada j aporta una recta de pendiente b[j] e intercepto dp[j]. Consultas su mínimo en x=a[i].\n\nSi las pendientes o las consultas no llegan en orden, una deque sencilla puede fallar. Puedes mantener los puntos donde cambia la recta ganadora o dividir el dominio con un árbol Li Chao. Ambos métodos aprovechan que dos rectas se cruzan como mucho una vez."),
      s("Qué guarda Li Chao","En un nodo de [L,R], conserva la mejor recta candidata en el punto medio. Al insertar otra, intercámbialas si la nueva gana allí. La perdedora solo puede mejorar en una mitad; compara un extremo para decidir dónde continuar.\n\nPara consultar x, evalúa las rectas del camino hacia x y toma el mínimo. La recta guardada no tiene por qué ganar en todo el intervalo."),
      s("Dos rectas que cambian de orden","Inserta f(x)=2x+1 y g(x)=−x+7 sobre enteros de cero a ocho. En el centro, x=4, g vale tres y f nueve: g puede quedarse en la raíz.\n\nEn x=0, f vale uno y g siete, así que conserva f hacia la izquierda. Se igualan en x=2. Las consultas x=1 y x=6 devuelven tres y uno. Prueba también pendientes iguales y empates."),
      s("Dominio y precisión","En un dominio entero de tamaño C, Li Chao tarda O(log C) por inserción y consulta. Si conoces las q coordenadas consultadas, comprímelas y divide por índices: cuesta O(log q), evaluando siempre las coordenadas originales.\n\nUna envolvente dinámica puede dar O(log n) amortizado, pero requiere divisiones enteras con redondeo correcto. Usa un tipo suficientemente ancho para pendiente·x+intercepto y comprueba rectas paralelas y coordenadas extremas.")
    ],q('¿Qué garantiza una recta almacenada en un nodo Li Chao?', ['Ganar en todos sus puntos','Ganar en su punto medio entre las candidatas comparadas','Tener menor pendiente'],1,'El punto medio decide cuál se conserva; la recta perdedora puede mejorar una mitad y por eso desciende.')),

  a('lagrange','Relajación lagrangiana: poner precio a una restricción','Elimina una dimensión de conteo mediante una penalización y estudia cuándo puedes recuperar la respuesta exacta.',
    ['usaco-gold-intro-dp','usaco-silver-binary-search','usaco-plat-convex-hull-trick'],['Optimizar valor y cantidad con una penalización','Justificar la condición de concavidad discreta'],[
      s("Poner un precio a cada grupo","Quieres el mayor beneficio usando exactamente K grupos. Si guardar K en la DP cuesta demasiado, prueba una penalización λ y maximiza beneficio−λ·grupos. Guarda también cuántos grupos elegiste.\n\nAl aumentar el precio, puedes elegir una cantidad óptima que no aumente. Eso permite buscar λ, pero no asegura encontrar todos los conteos: algunos valores de K pueden quedar entre dos saltos."),
      s("La condición de concavidad","Sea F(k) el mejor beneficio con k unidades. Si las mejoras F(k)−F(k−1) no aumentan, F es discretamente cóncava. Un precio de soporte adecuado permite recuperar F(K) sumando λK al valor penalizado.\n\nSin esa propiedad, solo obtienes información de la envolvente cóncava, que puede quedar por encima del beneficio real. Necesitas demostrar la concavidad del problema antes de usar la recuperación."),
      s("Un empate entre varios conteos","Toma F=[0,8,13,18], con mejoras 8,5,5. Para λ=6, los valores penalizados son 0,2,1,0: eliges un grupo. Para λ=5 son 0,3,3,3. Si desempatas hacia la mayor cantidad, eliges tres.\n\nAunque buscas K=2, recuperas 3+5·2=13. Funciona porque los conteos están en el mismo tramo lineal. Usa el mismo criterio de desempate en todas las transiciones."),
      s("Costo y comprobación","Si evaluar λ cuesta T(n) y buscas precios enteros en un intervalo de amplitud W, el costo es O(T(n) log W). Para precios reales debes analizar precisión y recuperación por separado.\n\nConstruye primero una DP pequeña que calcule todos los F(k), por ejemplo al elegir subarreglos disjuntos. Compara sus diferencias con la versión penalizada. Define si necesitas exactamente K grupos o como mucho K: son objetivos distintos.")
    ],q('¿Por qué la monotonicidad del conteo no basta para recuperar F(K)?', ['Porque λ nunca puede ser entero','Porque K puede quedar debajo de la envolvente sin concavidad','Porque la búsqueda binaria necesita números positivos'],1,'Los precios solo seleccionan puntos soportados por rectas; un punto no cóncavo puede no ser óptimo para ningún precio.')),

  a('slope-trick','Slope trick: programar con funciones convexas','Representa cambios de pendiente y transforma una DP que vive sobre muchas posiciones.',
    ['usaco-silver-priority-queues','usaco-plat-convex-hull-trick'],['Representar funciones convexas lineales por tramos','Aplicar valor absoluto y mínimos de prefijo'],[
      s("Guardar cambios de pendiente","La función |x−a| baja con pendiente −1 antes de a y sube con pendiente +1 después. En una función convexa lineal por tramos, las pendientes solo aumentan.\n\nPuedes guardar sus esquinas y un valor base en lugar de evaluar cada x. Slope trick organiza esa información en montículos para aplicar ciertas transiciones de DP sin recorrer todo el dominio."),
      s("Una secuencia no decreciente","Quieres ajustar a[i] a valores b[i] no decrecientes, pagando Σ|a[i]−b[i]|. Define F_i(x) como el menor costo si b[i]=x. Entonces F_i(x)=|x−a[i]|+min(y≤x)F_{i−1}(y).\n\nEl mínimo de prefijo conserva la parte descendente de una función convexa y vuelve horizontal la parte posterior al mínimo. Esa transformación se puede mantener mediante cambios de pendiente en un montículo."),
      s("Ajustar dos valores","Para a=[3,1], empiezas con F_1(x)=|x−3|. Su mínimo de prefijo vale 3−x si x<3 y cero si x≥3. Al agregar |x−1|, el costo mínimo es dos: sirven [1,1] o [2,2].\n\nEn la implementación de este problema, inserta cada a dos veces en un max-heap y quita una vez el máximo. Si ese máximo supera a, agrega la diferencia al costo."),
      s("Qué operaciones admite","Esta variante tarda O(n log n) y ocupa O(n). Una implementación general puede usar dos montículos, desplazamientos diferidos y el valor mínimo para manejar bisagras y traslaciones. Cada transformación debe conservar convexidad.\n\nCalcula las pendientes para [5,2,4] y compara con enumerar secuencias b pequeñas. Si necesitas reconstruir b, guarda información adicional: conocer el costo mínimo no te dice por sí solo qué valores lo producen.")
    ],q('¿Qué hace min(y≤x)F(y) a una función convexa?', ['La vuelve constante en todo el dominio','Mantiene la bajada y aplana la parte posterior al mínimo','Invierte todas sus pendientes'],1,'Antes del mínimo conviene y=x; después, ya puede elegirse un minimizador anterior y el resultado permanece en el mínimo.')),

  a('sp-neg','Caminos mínimos con aristas negativas','Aprende Bellman–Ford, ciclos negativos y potenciales para recuperar pesos no negativos.',
    ['usaco-gold-shortest-paths'],['Detectar ciclos negativos alcanzables','Comprender reponderación mediante potenciales'],[
      s("Una arista que abarata una ruta anterior","Desde s puedes ir a a con costo dos o a b con costo cinco. Si b→a cuesta −10, la ruta por b llega a a con costo −5. Cerrar a con distancia dos, como haría la regla usual de Dijkstra, sería prematuro.\n\nUn peso negativo no implica que falte una respuesta. El problema aparece si puedes repetir un ciclo negativo dentro de una ruta relevante."),
      s("Relajar con Bellman–Ford","Inicializa dist[s]=0 y las demás distancias en infinito. En cada ronda revisa todas las aristas u→v: si u es alcanzable, intenta mejorar dist[v] con dist[u]+w. Tras n−1 rondas cubres todas las rutas simples necesarias.\n\nSi otra ronda mejora alguna distancia, hay un ciclo negativo alcanzable desde s. Para que afecte al destino t, además debe poder llegar a t. Propaga desde los vértices mejorados para comprobarlo."),
      s("Reponderar con potenciales","Si no hay ciclos negativos, agrega una superfuente con aristas de costo cero y calcula h con Bellman–Ford. Cambia los pesos a w'(u,v)=w(u,v)+h[u]−h[v]. Como h[v]≤h[u]+w, todos quedan no negativos.\n\nEn una ruta se cancelan los potenciales interiores: solo añades h[s]−h[t]. El orden entre rutas de iguales extremos se conserva. Aplica Dijkstra y recupera dist(s,t)=dist'(s,t)−h[s]+h[t]."),
      s("Tiempo y casos límite","Bellman–Ford tarda O(nm) y ocupa O(n+m), contando el grafo. Puedes parar si una ronda no cambia nada. Johnson agrega Dijkstra por origen: O(nm+n(m+n) log n) con heap binario. SPFA también puede tardar O(nm) en el peor caso.\n\nPrueba componentes separadas, aristas paralelas y ciclos negativos que no alcancen al destino. No sumes pesos a infinito y usa un tipo ancho para las distancias.")
    ],q('Un ciclo negativo es alcanzable desde s, pero no puede llegar a t. ¿Implica dist(s,t)=−∞?', ['Sí, siempre','No; debe poder influir en una ruta hasta t','Solo si tiene tres vértices'],1,'Para reducir indefinidamente una ruta s→t hay que llegar al ciclo, repetirlo y salir hacia t.')),

  a('eulerian-tours','Recorridos eulerianos y algoritmo de Hierholzer','Recorre cada arista exactamente una vez y distingue esta tarea de visitar cada vértice.',
    ['usaco-silver-graph-traversal'],['Reconocer las condiciones de existencia','Construir recorridos con identificadores de arista'],[
      s("Recorrer cada arista una vez","Un recorrido euleriano usa cada arista exactamente una vez y puede repetir vértices. En un grafo no dirigido con aristas, los vértices de grado positivo deben estar conectados. Hay circuito si todos sus grados son pares; camino abierto, si exactamente dos son impares.\n\nEn uno dirigido, un camino abierto necesita salida−entrada=1 al inicio, entrada−salida=1 al final y balance cero en los demás, además de conectividad débil entre los vértices con aristas."),
      s("Construcción con una pila","Hierholzer empieza con el vértice inicial en una pila. Si la cima tiene una arista sin usar, consúmela y agrega su vecino. Si ya no tiene salida, retírala y añádela a la respuesta. Al terminar, invierte la respuesta.\n\nEn un grafo no dirigido, las dos entradas de una arista comparten identificador y una marca used. Marcar vértices no sirve, porque puedes visitarlos varias veces."),
      s("Un circuito triangular","En 0–1–2–0, todos los grados son dos. Recorres 0,1,2,0; después vacías la pila. Invertir lo acumulado recupera el circuito. El programa usa identificadores para consumir las aristas de este ejemplo.\n\nPara una entrada general, comprueba las condiciones y elige un inicio válido. Al finalizar deben quedar m+1 vértices en la respuesta. Si faltan, no recorriste todas las aristas.", String.raw`#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>
using namespace std;
int main(){
  vector<vector<pair<int,int>>> g(3);
  auto add=[&](int u,int v,int id){g[u].push_back({v,id});g[v].push_back({u,id});};
  add(0,1,0); add(1,2,1); add(2,0,2);
  vector<int> pos(3), stack={0}, answer;
  vector<bool> used(3);
  while(!stack.empty()){
    int u=stack.back();
    while(pos[u]<(int)g[u].size() && used[g[u][pos[u]].second]) ++pos[u];
    if(pos[u]==(int)g[u].size()){answer.push_back(u);stack.pop_back();}
    else {auto [v,id]=g[u][pos[u]++];used[id]=true;stack.push_back(v);}
  }
  reverse(answer.begin(),answer.end());
  for(int v:answer) cout<<v<<' ';
  cout<<'\n';
}`),
      s("Costo y aristas especiales","Con un puntero por vértice, revisas cada entrada de adyacencia como mucho una vez. El tiempo y la memoria son O(n+m). Volver a buscar desde el inicio una arista disponible puede empeorar esa cota.\n\nPrueba aristas paralelas, un lazo y una cadena. También puedes representar palabras mediante aristas entre sus prefijos y sufijos. Antes de aplicar las condiciones, identifica si el modelo es dirigido.")
    ],q('¿Cuántos vértices tiene la lista de un recorrido que consume m aristas?', ['m−1','m','m+1'],2,'Cada arista agrega una transición; la lista incluye además el vértice inicial.')),

  a('BCC-2CC','Puentes, articulaciones y componentes biconexas','Identifica puntos únicos de falla y comprime regiones que conservan conectividad.',
    ['usaco-silver-graph-traversal','usaco-gold-dsu'],['Interpretar low-link en un DFS no dirigido','Distinguir falla de arista y falla de vértice'],[
      s("Quitar una arista o un vértice","Una arista es puente si borrarla aumenta las componentes. Un vértice es articulación si borrarlo junto con sus aristas aumenta esa cantidad.\n\nDos triángulos que comparten un vértice no tienen puentes, pero ese vértice sí es articulación. Por eso las componentes tras quitar puentes son distintas de los bloques biconexos por vértices. La pregunta determina cuál de las dos estructuras necesitas construir."),
      s("Tiempos de entrada y low","En DFS, tin[u] registra cuándo entras a u. low[u] es el menor tiempo alcanzable desde su subárbol siguiendo aristas del árbol y como mucho una de regreso.\n\nPara un hijo v, u–v es puente si low[v]>tin[u]: no puede volver a u ni más arriba. Si u no es raíz, es articulación si algún hijo cumple low[v]≥tin[u]. Volver solo a u no ayuda cuando precisamente eliminas u."),
      s("Extraer las componentes","Con 0–1,1–2,2–0,1–3, la arista 1–3 es puente y el vértice uno es articulación. Para obtener componentes separadas por puentes, recorre el grafo ignorándolos.\n\nPara bloques por vértices, guarda aristas en una pila DFS. Cuando low[v]≥tin[u], retira hasta u–v para formar un bloque. La raíz tiene una regla propia: es articulación si posee al menos dos hijos DFS."),
      s("Multigrafos y comprobación","Ambos algoritmos cuestan O(n+m) tiempo y memoria. En un multigrafo, ignora solo la arista padre por identificador: otra arista paralela hacia el padre puede evitar un puente. Recorre todas las componentes y revisa la profundidad de recursión.\n\nCompara con quitar cada arista o vértice en grafos pequeños. Después puedes comprimir componentes y usar LCA para contar cuántos puentes separan dos ciudades.")
    ],q('Para un hijo DFS v de u, ¿cuándo es puente u–v?', ['low[v]≥tin[u]','low[v]>tin[u]','low[v]<tin[u]'],1,'Si low[v]=tin[u], hay una ruta de regreso a u y la arista no es un puente; se necesita desigualdad estricta.')),

  a('SCC','Componentes fuertemente conexas y 2-SAT','Agrupa vértices mutuamente alcanzables y razona sobre dependencias sin ciclos.',
    ['usaco-gold-toposort','usaco-silver-graph-traversal'],['Construir la condensación de un grafo dirigido','Reducir restricciones booleanas a implicaciones'],[
      s("Poder ir y volver","Dos vértices de un grafo dirigido están en la misma componente fuertemente conexa si cada uno puede llegar al otro. Al comprimir esos grupos obtienes un DAG.\n\nSi quedara un ciclo entre grupos, todos sus vértices podrían alcanzarse mutuamente y deberían formar una sola componente. Esta condensación permite aplicar orden topológico o DP aunque el grafo original tenga ciclos."),
      s("Las dos pasadas de Kosaraju","Haz DFS en el grafo original y agrega cada vértice a una lista cuando termines de explorarlo. Después invierte las aristas y procesa esa lista en orden inverso. Cada nueva DFS encuentra una componente.\n\nEl orden evita que una búsqueda escape hacia otra componente aún sin asignar. Tarjan ofrece una alternativa con low-link y una pila de vértices activos. Sus reglas no son las de los puentes en grafos no dirigidos."),
      s("Componentes y 2-SAT","En 0→1,1→0,1→2,2→3,3→2, los grupos son {0,1} y {2,3}, conectados en ese orden.\n\nPara 2-SAT, transforma (a o b) en no a→b y no b→a. Usa un vértice por literal. No hay solución exactamente cuando una variable y su negación comparten componente. Para obtener una asignación, usa el orden entre componentes; la comparación de sus identificadores depende de cómo los numeraste."),
      s("Costo y validación de asignaciones","Kosaraju cuesta O(n+m) tiempo y memoria, incluido el grafo inverso. Para v variables y c cláusulas, el tamaño de 2-SAT es O(v+c).\n\nComprueba la asignación final contra todas las cláusulas. Con tres variables puedes enumerar las ocho posibilidades y comparar. Incluye (x o x), contradicciones y vértices aislados. Para grafos muy profundos, una pila iterativa evita desbordar la pila de llamadas.")
    ],q('¿Qué contradicción detecta 2-SAT mediante componentes?', ['Dos variables distintas en una SCC','x y no x en la misma SCC','Una SCC con un solo vértice'],1,'Las implicaciones obligarían simultáneamente a alcanzar una afirmación y su negación; ninguna elección de x puede satisfacerlas.')),

  a('offline-del','Borrados offline y DSU con rollback','Convierte aristas que aparecen y desaparecen en intervalos sobre el tiempo.',
    ['usaco-gold-dsu','usaco-plat-segtree-ext'],['Registrar cambios reversibles en DSU','Recorrer un árbol de intervalos de actividad'],[
      s("Convertir borrados en intervalos","Un DSU une componentes, pero no sabe separarlas al borrar una arista. Si conoces las operaciones de antemano, representa cada arista mediante el intervalo de tiempo en que está activa.\n\nUn árbol de segmentos sobre el tiempo guarda esa arista en O(log q) nodos. Al entrar a un nodo, agregas sus aristas; al salir, deshaces los cambios. Así cada rama trabaja con el estado que le corresponde."),
      s("Guardar cambios para deshacerlos","Usa unión por tamaño sin compresión de caminos. Una unión exitosa apila la raíz absorbida, el tamaño anterior del ganador y los agregados que modificaste. Una instantánea es el tamaño de esa pila.\n\nPara restaurarla, deshaz entradas hasta llegar a ese tamaño. Evitar compresión simplifica las escrituras que debes revertir. La unión por tamaño mantiene altura O(log n), así que find conserva una cota determinista."),
      s("Seguir el estado en el tiempo","Agrega 0–1 en t0, consulta 0 con 2 en t1, agrega 1–2 en t2 y consulta en t3. Borra 0–1 en t4 y vuelve a consultar en t5. Las respuestas son no, sí, no.\n\nLas aristas viven en [0,4) y [2,6). En cada hoja temporal has agregado exactamente las activas. Al volver de un hijo, restaura su instantánea antes de visitar al hermano."),
      s("Costo y multiplicidades","Con K intervalos y Q consultas, el costo es O((K log q+Q) log n), más el preprocesamiento; la memoria, O(n+K log q). Si agregas una arista varias veces, usa identificadores o cuenta copias: borrar una sola quizá no la desactive.\n\nDefine si cada consulta ve el estado anterior o posterior a la operación de su índice. Compara casos pequeños con BFS. Si solo hay borrados, también puedes procesar el tiempo al revés.")
    ],q('¿Por qué suele omitirse la compresión de caminos en DSU con rollback?', ['Porque rompe conectividad','Porque introduce muchas escrituras que también habría que deshacer','Porque unión por tamaño deja de funcionar'],1,'Rollback necesita restaurar cada cambio; unión por tamaño sin compresión mantiene find en O(log n) con un registro sencillo.')),

  a('eulers-formula','Fórmula de Euler y grafos planares','Relaciona vértices, aristas y regiones y comprueba cuándo un dibujo permite aplicar la fórmula.',
    ['usaco-bronze-intro-graphs','usaco-plat-geo-pri'],['Contar la cara exterior y las componentes','Obtener límites de aristas en grafos simples planares'],[
      s("Contar también el exterior","En un dibujo planar, las aristas solo se cruzan en sus extremos. Si hay V vértices, E aristas, F caras y C componentes, se cumple V−E+F=1+C. F incluye la cara exterior. Para un grafo conexo queda V−E+F=2.\n\nSi decides que un cruce interior de segmentos es una conexión, conviértelo en vértice y divide las aristas antes de contar."),
      s("Cómo cambia la cuenta al agregar aristas","Un bosque con C componentes tiene E=V−C y una sola cara: cumple la fórmula. Si agregas una arista entre componentes, E aumenta uno y C baja uno, sin crear caras.\n\nSi sus extremos ya estaban conectados, cierras un ciclo que divide una cara en dos. E y F aumentan uno. En ambos casos conservas la igualdad. Un puente tiene dos lados, pero no crea una cara nueva."),
      s("Dos dibujos pequeños","Un cuadrado con diagonal tiene V=4, E=5, F=3: dos triángulos y el exterior. Dos cuadrados separados tienen V=8, E=8, C=2, F=3; comparten la misma cara exterior.\n\nPara un grafo simple planar conexo con V≥3, las incidencias de caras dan 3F≤2E y, junto con Euler, E≤3V−6. K5 tiene diez aristas y cinco vértices: diez supera nueve, así que no es planar."),
      s("Qué demuestra la fórmula","Con los conteos conocidos, evaluar Euler cuesta O(1). Obtener las intersecciones de un dibujo puede requerir mucho más trabajo, por ejemplo un barrido. E≤3V−6 es una condición necesaria, pero no basta para demostrar planaridad.\n\nRevisa las hipótesis si hay lazos, aristas paralelas o menos de tres vértices. Dibuja dos ciclos unidos por un puente y cuenta sus caras. Un DSU también permite detectar qué nuevas conexiones cierran ciclos.")
    ],q('Dos triángulos separados tienen V=6, E=6 y C=2. ¿Cuántas caras hay?', ['2','3','4'],1,'F=1+C−V+E=3: dos interiores y una única región exterior.')),

  a('critical','Dominadores: ciudades que toda ruta debe atravesar','Reconoce vértices inevitables desde un origen y aprende la estructura del árbol de dominadores.',
    ['usaco-silver-graph-traversal','usaco-gold-toposort'],['Definir dominación con todas las rutas dirigidas','Distinguir dominadores, articulaciones y semidominadores'],[
      s("Un paso obligado desde el origen","Fija un origen s. Un vértice d domina a v si todo camino de s a v pasa por d. Solo consideramos vértices alcanzables. s y v siempre dominan a v.\n\nEn s→a→t y s→b→t, ni a ni b domina t. Si t→u es la única entrada a u, t sí domina u. Esta propiedad depende del origen y de la dirección de las aristas."),
      s("Calcular conjuntos de dominadores","Dom(s)={s}. Para otro v, Dom(v)={v} unido con la intersección de Dom(p) sobre sus predecesores alcanzables. En un DAG puedes calcularlo en orden topológico.\n\nCon ciclos, inicia los conjuntos no iniciales con todos los alcanzables e itera hasta que no cambien. Solo disminuyen, pero una pasada DFS no basta. Con bitsets de palabras de w bits, cada ronda cuesta O((n+m)·ceil(n/w)); incluye la cantidad de rondas en el costo total."),
      s("El árbol de dominadores","Los dominadores estrictos de v forman una cadena. El más cercano se llama idom(v), su dominador inmediato. Estos enlaces forman un árbol con raíz s. Para encontrar los vértices obligados hacia t, sube desde t hasta s.\n\nLengauer–Tarjan evita guardar conjuntos completos mediante numeración DFS, semidominadores y operaciones link/eval. Un semidominador es información auxiliar definida con restricciones de numeración; no es necesariamente idom."),
      s("Comprobar antes de optimizar","Como referencia, elimina cada candidato y vuelve a buscar desde s. Cuesta O(n(n+m)) y sirve en grafos pequeños. Compara diamantes, ciclos y vértices inalcanzables con el árbol calculado.\n\nLengauer–Tarjan tiene variantes O((n+m) log n) y otras casi lineales con unión balanceada. La cota depende de cómo implementes link/eval. El mismo concepto de paso obligado se usa al analizar el flujo de control de un programa.")
    ],q('En s→a→t y s→b→t, ¿quiénes dominan t?', ['s, a y t','s y t','Todos los vértices'],1,'Hay una ruta que evita a y otra que evita b; ambas deben pasar por s y terminar en t.')),

  a('link-cut-tree','Link-cut trees: bosques que cambian','Mantén caminos de un bosque mientras enlazas y cortas aristas.',
    ['usaco-adv-treaps','usaco-plat-hld'],['Separar el bosque representado de los árboles auxiliares','Entender access, makeroot, link y cut'],[
      s("Un bosque que cambia","HLD divide caminos de un árbol fijo. Si conectas árboles o cortas aristas, esa división puede dejar de servir. Un link-cut tree mantiene caminos preferidos en árboles auxiliares splay.\n\nDistingue ambos niveles: un padre dentro del splay no tiene por qué ser el padre directo en el bosque original. Las operaciones auxiliares reorganizan la representación para consultar caminos."),
      s("Exponer el camino que necesitas","access(v) reorganiza los caminos preferidos para exponer desde la raíz representada hasta v. Después, splay(v) permite consultar su agregado. makeroot(v) hace access y aplica una inversión diferida para cambiar la raíz representada.\n\nPara consultar u–v, usa makeroot(u), access(v) y lee el agregado del splay de v. Para sumas o máximos basta un resumen; si importa la orientación, guarda ambos sentidos."),
      s("Conectar y cortar","En los árboles 1–2–3 y 4–5, link(3,4) forma 1–2–3–4–5. Comprueba antes que los extremos estén en árboles distintos; si no, crearías un ciclo.\n\ncut(2,3) debe borrar una arista real. Tras makeroot(2) y access(3), verifica que sean adyacentes antes de modificar enlaces. No basta con que exista un camino entre ellos. Después del corte, uno y cinco quedan desconectados."),
      s("Costo y pruebas de operaciones","Las operaciones estándar cuestan O(log n) amortizado y la memoria es O(n). Una operación aislada puede tardar más. Antes de rotar, propaga las inversiones de los ancestros auxiliares; después, recalcula los agregados.\n\nConsultar subárboles requiere contribuciones virtuales adicionales. Compara en bosques pequeños con BFS y reconstrucción explícita de caminos. En cada función, distingue la raíz del splay de la raíz representada.")
    ],q('¿Cuándo es válida link(u,v) en un bosque dinámico?', ['Siempre que u≠v','Cuando u y v están en componentes distintas','Solo cuando ambos son hojas'],1,'Si ya están conectados, añadir la arista cerraría un ciclo; un link-cut tree estándar representa bosques.')),

  a('comb-sub','DP de árboles: combinar subárboles','Mezcla presupuestos o cantidades entre hijos sin atribuir un costo cúbico innecesario.',
    ['usaco-gold-dp-trees','usaco-gold-knapsack'],['Derivar una convolución min-plus entre hijos','Acotar el trabajo usando tamaños reales de subárboles'],[
      s("Una tabla por subárbol","Define dp[u][k] como el menor costo de elegir k objetos del subárbol de u. Cada hijo aporta opciones que debes combinar, como en una mochila.\n\nSi un descuento depende de elegir al padre, agrega un estado booleano y define qué opciones del hijo son compatibles. El estado debe guardar toda la información que cambie las decisiones posteriores, sin esconder dependencias con otros ancestros."),
      s("Combinar un hijo nuevo","Sea A la tabla de los hijos ya procesados y B la del siguiente. Calcula C[k]=min(i+j=k)(A[i]+B[j]). Inicializa C en infinito y escríbela en un arreglo nuevo para no usar al mismo hijo más de una vez.\n\nRecorre i hasta los objetos procesados y j hasta el tamaño real del hijo. El rango válido crece al incorporar ese hijo; no necesitas recorrer siempre hasta n."),
      s("Combinar dos tablas pequeñas","Con A=[0,4,9] y B=[0,3], el índice dice cuántos objetos eliges. Obtienes C[0]=0 y C[1]=min(4,3)=3. Para dos objetos, C[2]=min(9,4+3)=7. Para tres, C[3]=9+3=12.\n\nCon presupuesto ocho puedes comprar dos. Elegir por separado lo más barato de cada hijo no basta: sus tablas pueden contener dependencias internas. Debes comparar combinaciones para cada cantidad exacta."),
      s("Contar las parejas procesadas","Mezclar bloques de tamaños a y b cuesta O(ab), además de términos lineales. Cada pareja de objetos de bloques distintos se encuentra una vez, cuando esos bloques se unen. Con tamaños reales y una cantidad constante de estados, el total es O(n²).\n\nGuardar todas las tablas puede ocupar O(n²); liberar las ya incorporadas puede reducirlo. Prueba cadenas y estrellas, cuenta transiciones y compara con enumerar subconjuntos para n≤15.")
    ],q('¿Por qué no hay necesariamente n³ transiciones al combinar subárboles?', ['Porque todo árbol tiene altura logarítmica','Porque cada pareja de objetos se junta por primera vez una sola vez','Porque cada tabla tiene longitud dos'],1,'Usando tamaños reales, la suma de productos de tamaños de bloques se carga a pares de objetos y es O(n²).')),

  a('dp-broken-profile','DP de perfiles: una frontera pequeña en una cuadrícula','Cuenta colocaciones recorriendo celdas y recordando solamente lo que cruza la frontera.',
    ['usaco-gold-dp-bitmasks','usaco-gold-paths-grids'],['Definir una máscara de frontera sin ambigüedad','Reducir una dimensión grande a pasos de una DP'],[
      s("Recordar solo la frontera","Un tablero puede tener miles de columnas y ocho filas. Al recorrerlo, no necesitas guardar todas las colocaciones anteriores: solo cómo afectan a las celdas que faltan.\n\nUna máscara de w bits puede indicar qué posiciones ya están ocupadas por piezas que cruzan la frontera. Si el problema exige conectividad, la ocupación quizá no baste: también tendrás que recordar qué partes están conectadas."),
      s("Colocar dominós","Recorre por columnas y luego por filas. Si la celda ya está ocupada, consume su marca y avanza. Si está libre, prueba un dominó vertical cuando quepa la fila siguiente y esté libre; prueba uno horizontal cuando quede otra columna.\n\nEl horizontal deja una marca para esa fila en la siguiente columna. Define cada bit con cuidado: en una frontera parcialmente recorrida, algunos describen la columna actual y otros la próxima."),
      s("Tablero de dos por tres","Hay tres recubrimientos: tres dominós verticales; dos horizontales al principio y uno vertical al final; o uno vertical al principio y dos horizontales después.\n\nEmpiezas con máscara cero. Dos horizontales salientes dejan 11; la siguiente columna consume ambas marcas y vuelve a cero. Al terminar solo aceptas máscara cero. Un bit pendiente significaría que una pieza continúa fuera del tablero."),
      s("Costo según la anchura","Con w como dimensión pequeña y h como la otra, procesar celda a celda con una cantidad constante de transiciones cuesta O(h·w·2^w). Dos capas de DP ocupan O(2^w). Si precalculas transiciones por columna, cuenta cuántas parejas de máscaras generas antes de atribuirle la misma cota.\n\nPrueba obstáculos y áreas impares, que deben dar cero. Para caminos conectados, necesitas etiquetas de componentes y una forma de normalizar las equivalentes.")
    ],q('¿Qué máscara se acepta después de procesar toda la cuadrícula?', ['Cualquier máscara','La máscara de todos unos','Cero'],2,'Un bit pendiente indica ocupación que cruza hacia celdas inexistentes; un recubrimiento completo termina sin compromisos abiertos.')),

  a('dp-more','Más técnicas de DP: Knuth y componentes','Aprovecha monotonía de particiones y cuenta estructuras según sus bloques abiertos.',
    ['usaco-gold-dp-ranges','usaco-plat-dc-dp','usaco-gold-combo'],['Verificar las hipótesis de optimización de Knuth','Construir estados basados en componentes parciales'],[
      s("Limitar los cortes con Knuth","En dp[l][r]=cost(l,r)+min(l≤k<r){dp[l][k]+dp[k+1][r]}, con dp[i][i]=0, probar todos los cortes cuesta O(n³). Knuth permite buscar k entre opt[l][r−1] y opt[l+1][r].\n\nUna condición suficiente exige, para a≤b≤c≤d, cost(b,c)≤cost(a,d) y cost(a,c)+cost(b,d)≤cost(a,d)+cost(b,c). Comprueba ambas para tu costo real; los signos pueden cambiar si son válidas."),
      s("Fusionar montones vecinos","Para [2,3,4], fusionar paga la suma del bloque. Con tamaños no negativos, las sumas de intervalo cumplen las condiciones de Knuth y se calculan con prefijos. Primero dp[0][1]=5 y dp[1][2]=7.\n\nAl unir los tres, cortar después del primero cuesta 0+7+9=16; después del segundo, 5+0+9=14. Guarda el mejor corte y desempata siempre igual. Los límites óptimos reducen el total a O(n²), con O(n²) memoria."),
      s("Contar componentes parciales","En otras DP agregas elementos y guardas cuántos bloques quedan abiertos. El nuevo elemento puede abrir uno, extender otro o unir dos, cambiando el conteo por +1, cero o −1. Un posible estado es dp[i][c].\n\nQuizá necesites indicadores para extremos especiales. Los factores de cada transición dependen de los lados disponibles y de si los bloques tienen orientación. Derívalos del problema; no hay una fórmula universal."),
      s("Comparar con una versión pequeña","Para Knuth, calcula todos los cortes en entradas pequeñas y compara. Observar monotonía ayuda a detectar errores, pero todavía necesitas demostrarla. Los costos negativos permiten comprobar dónde falla el ejemplo de montones.\n\nPara componentes, enumera permutaciones de cuatro elementos y agrúpalas por estado. Si dos configuraciones del mismo estado admiten transiciones distintas, falta información. O(n²) estados con transiciones constantes cuestan O(n²); dimensiones extra multiplican el costo.")
    ],q('¿Qué debes justificar antes de aplicar Knuth?', ['Que n sea potencia de dos','Las propiedades del costo que garantizan monotonía de opt','Que todos los cortes den el mismo costo'],1,'La restricción de candidatos solo es válida bajo las condiciones de monotonía; de otro modo puede excluir el corte óptimo.')),

  a('max-flow','Flujo máximo y redes residuales','Modela cantidades que atraviesan una red y permite deshacer elecciones anteriores.',
    ['usaco-gold-unweighted-shortest-paths','usaco-gold-shortest-paths'],['Mantener capacidad y conservación','Explicar caminos aumentantes y Dinic'],[
      s("Capacidades y conservación","Piensa en enviar recursos por una red. Cada arista dirigida tiene una capacidad máxima no negativa. La fuente s los envía y el sumidero t los recibe. En cada vértice intermedio, lo que entra debe salir.\n\nBusca la mayor cantidad neta que sale de s. Puedes modelar transporte o asignaciones entre estudiantes y talleres. Antes de programar, define qué representa una unidad de flujo y qué limita cada capacidad."),
      s("La red residual","En una arista de capacidad c que lleva f, todavía puedes enviar c−f hacia delante. También puedes cancelar hasta f mediante la arista residual inversa.\n\nSi encuentras un camino residual s→t, aumenta el flujo por la menor capacidad del camino. Actualiza cada arista y su inversa para conservar las cantidades. Guarda índices explícitos de las parejas; así distingues aristas paralelas y aristas originales en ambos sentidos."),
      s("Niveles de Dinic","Con capacidades s→a=3, s→b=2, a→t=2 y b→t=4, puedes enviar cuatro: dos por cada rama. La fuente tiene capacidad total cinco, pero la salida de a limita esa rama.\n\nDinic calcula niveles con BFS sobre el residual. Después envía un flujo bloqueante por aristas que avanzan un nivel. Los punteros de arista actual evitan revisar una y otra vez las conexiones agotadas de esa fase."),
      s("Costo y comprobación","Dinic general tarda O(V²E) y ocupa O(V+E). Algunas redes admiten mejores cotas; debes justificar sus condiciones. Con capacidades enteras, los aumentos también son enteros, lo que permite interpretar el resultado como asignaciones.\n\nPrueba emparejamientos con capacidades uno. Revisa conservación y capacidades de cada arista, y compara redes pequeñas con todos sus cortes. Usa un límite seguro para el flujo total en lugar de un infinito que desborde.")
    ],q('¿Qué representa una capacidad residual inversa de 5?', ['Una capacidad original obligatoria de 5','La posibilidad de cancelar hasta 5 unidades de flujo previo','Un ciclo negativo'],1,'El residual inverso permite revisar decisiones sin violar el flujo original; su capacidad coincide con la cantidad cancelable.')),

  a('min-cut','Corte mínimo y modelos de decisión','Transforma conflictos y costos de selección en una separación entre fuente y sumidero.',
    ['usaco-adv-max-flow'],['Recuperar un corte a partir del residual','Modelar costos y restricciones con aristas'],[
      s("Separar fuente y sumidero","Un corte divide los vértices en S y T, con la fuente en S y el sumidero en T. Suma las capacidades de las aristas dirigidas de S a T. Las de vuelta no se añaden a esa capacidad.\n\nCualquier flujo tiene valor como mucho igual al corte. El teorema de flujo máximo y corte mínimo garantiza que algún corte alcanza exactamente el valor del mayor flujo."),
      s("Recuperar el corte","Después del flujo máximo, busca desde s usando todas las aristas con capacidad residual positiva, incluidas las inversas. Los alcanzados forman S. t debe quedar fuera: si lo alcanzaras, todavía podrías aumentar el flujo.\n\nLas aristas originales de S a T están saturadas. Suma sus capacidades originales y comprueba que coincidan con el flujo obtenido. Esa igualdad permite verificar el resultado."),
      s("Elegir proyectos con dependencias","Para un proyecto de beneficio p, agrega s→v con capacidad p. Para uno de costo c, agrega v→t con capacidad c. Si elegir u exige elegir v, agrega u→v con capacidad M mayor que la suma de beneficios positivos. S representa los proyectos elegidos.\n\nSi A gana ocho, B cuesta tres y A requiere B, elegir ambos deja cinco. El corte cuesta tres; réstalo de los ocho de beneficio total."),
      s("Comprobar la reducción","La red añade O(V+E) tamaño y el algoritmo de flujo determina el costo principal. M solo necesita superar cualquier corte admisible para que resulte imposible violar una dependencia en una solución óptima.\n\nEnumera las elecciones de cuatro proyectos y compara. Otro uso es recuperar una cobertura mínima de vértices en un grafo bipartito mediante un emparejamiento y su búsqueda alternante. No toda decisión binaria admite este modelo; justifica cada interacción.")
    ],q('Tras flujo máximo, ¿qué conjunto define un lado de un corte mínimo?', ['Los vértices de grado par','Los alcanzables desde s por aristas residuales positivas','Los visitados en el primer BFS solamente'],1,'Si t fuera alcanzable habría un aumento; el conjunto residual final determina una frontera cuya capacidad iguala al flujo.')),

  a('flow-lb','Flujo con cotas inferiores','Exige cantidades mínimas por arista y convierte el problema en una circulación factible.',
    ['usaco-adv-max-flow','usaco-adv-min-cut'],['Traducir mínimos a balances por vértice','Comprobar factibilidad saturando demandas auxiliares'],[
      s("Imponer mínimos además de máximos","Un taller debe recibir entre dos y cinco estudiantes. Representa esa exigencia como l[e]≤f[e]≤u[e]. Escribe f[e]=l[e]+g[e]; ahora 0≤g[e]≤u[e]−l[e].\n\nColocar primero los mínimos puede romper la conservación. Calcula b[v]=mínimos entrantes−mínimos salientes. El flujo adicional debe cumplir salida(g)−entrada(g)=b[v]. Esa ecuación indica qué signo usar en la transformación."),
      s("Compensar los balances","Deja capacidad u−l en cada arista original. Si b[v]>0, agrega S→v de capacidad b[v]: el exceso recibido por los mínimos debe salir por la red original. Si b[v]<0, agrega v→T con capacidad −b[v].\n\nCalcula flujo máximo de S a T. Hay circulación factible si saturas todas las aristas que salen de S. Recupera f=l+g. Los balances suman cero, así que las cantidades auxiliares de oferta y demanda coinciden."),
      s("Un ciclo de dos vértices","Exige entre dos y cuatro en a→b y permite hasta tres en b→a. Los balances son b[a]=−2 y b[b]=2. Agrega S→b y a→T, de capacidad dos, y envía dos por b→a. Obtienes dos unidades en cada sentido.\n\nSi el problema original tiene fuente s y sumidero t, agrega primero t→s con capacidad suficiente. Esa arista convierte el flujo en una circulación."),
      s("Maximizar después de encontrar una solución","La transformación ocupa O(V+E) adicional, así que conserva el orden del algoritmo de flujo. Para maximizar s→t, encuentra una circulación factible, retira correctamente la red auxiliar y la arista artificial, y aumenta en el residual original. El flujo inicial de t→s es el valor base.\n\nConserva la posibilidad de cancelar flujo. Prueba una instancia imposible y localiza qué demanda quedó sin saturar. Cumplir cotas sin conservar flujo no produce una solución válida.")
    ],q('Si b[v]=entrada mínima−salida mínima es positivo, ¿qué arista auxiliar agregas?', ['v→T','S→v','s→t'],1,'v tiene exceso inicial y debe enviar flujo adicional por aristas originales; S→v proporciona esa cantidad en la red auxiliar.')),

  a('min-cost-flow','Flujo de costo mínimo','Envía una cantidad requerida eligiendo rutas y revisando asignaciones mediante costos residuales.',
    ['usaco-adv-max-flow','usaco-adv-sp-neg'],['Asignar costos opuestos a aristas inversas','Usar potenciales en caminos aumentantes de menor costo'],[
      s("Cuánto enviar y cuánto pagar","Cada arista tiene capacidad y precio por unidad. Puedes pedir enviar F unidades al menor costo, o maximizar primero el flujo y minimizar después su costo. Define el objetivo: si no exiges cantidad, enviar cero podría ser lo más barato.\n\nEn asignaciones de personas a tareas, las capacidades uno evitan repetir asignaciones y los costos representan tiempo, distancia o penalizaciones."),
      s("Cancelar también devuelve el costo","Una arista de costo c tiene inversa residual de costo −c. Cancelar una unidad devuelve lo que pagaste. Busca el camino residual más barato y envía hasta cumplir F o saturar una arista.\n\nSi una ruta cuesta siete y admite dos unidades, y otra cuesta tres y admite una, enviar dos cuesta 3+7=10. Las inversas permiten revisar elecciones anteriores cuando aparece una combinación mejor."),
      s("Usar Dijkstra con potenciales","Las aristas inversas pueden ser negativas. Usa potenciales h para que c'(u,v)=c(u,v)+h[u]−h[v] sea no negativo en la región relevante. Si hay costos negativos iniciales sin ciclos negativos alcanzables, obtén h con Bellman–Ford.\n\nDespués de Dijkstra, agrega la distancia reducida a h[v] solo en los alcanzables. Los potenciales interiores se cancelan y conservan el orden entre rutas. Calcula el costo con los pesos originales o con la conversión correcta."),
      s("Costo y condiciones","Con A aumentos y heap binario, el costo es O(VE+A(E+V) log V), incluida la inicialización Bellman–Ford. Con capacidades enteras, A≤F, pero esa cota puede ser grande. La versión sencilla supone que no hay ciclos negativos residuales aprovechables al empezar. Las circulaciones negativas requieren tratamiento adicional.\n\nCompara asignaciones pequeñas con todas las permutaciones. Verifica cantidad y costo. Usa un tipo ancho para capacidad·costo y distingue una demanda imposible de un costo alto.")
    ],q('Si enviar por u→v cuesta 4, ¿cuánto cuesta su inversa residual?', ['4','0','−4'],2,'Cancelar una unidad recupera exactamente las cuatro unidades de costo pagadas; por eso el costo inverso es opuesto.')),

  a('fft','FFT, NTT y convolución','Multiplica polinomios transformando coeficientes en evaluaciones y regresando después.',
    ['usaco-gold-modular','usaco-gold-combo'],['Reconocer una convolución en un conteo','Elegir una longitud y un dominio de transformación válidos'],[
      s("Sumar productos de parejas","El coeficiente k de A(x)B(x) es c[k]=Σ(i+j=k)a[i]b[j]. Esta operación se llama convolución. Con [1,2] y [3,4] obtienes [3,10,8], como al multiplicar (1+2x)(3+4x).\n\nSi los arreglos guardan frecuencias, c[k] cuenta parejas cuya suma es k. El cálculo directo revisa cada pareja y cuesta O(nm)."),
      s("Evaluar, multiplicar y recuperar","Un polinomio queda determinado por suficientes evaluaciones distintas. FFT usa raíces de la unidad y separa coeficientes pares e impares: A(x)=A_par(x²)+x·A_impar(x²). Las evaluaciones de x² sirven tanto para x como para −x.\n\nMultiplica las evaluaciones correspondientes de A y B y aplica la transformada inversa. Rellena con ceros hasta una potencia de dos N≥n+m−1 para que los grados altos no se mezclen con el principio."),
      s("Elegir la aritmética","La FFT compleja tiene errores de redondeo que dependen de la longitud y las magnitudes. La NTT usa raíces módulo un primo p: necesitas N divisor de p−1 y una raíz de orden N. El primo 998244353 permite potencias de dos hasta 2^23.\n\nLa inversa usa raíces inversas y multiplica por N⁻¹ módulo p. Para recuperar enteros grandes puedes necesitar varios primos y el teorema chino del resto."),
      s("Costo y comparación directa","T(N)=2T(N/2)+O(N) da O(N log N). Una implementación iterativa usa O(N) memoria. Mantén consistentes la normalización inversa, las raíces y la permutación de bits.\n\nCompara arreglos pequeños con el doble bucle. Prueba ceros, negativos normalizados módulo p y tamaños apenas mayores que una potencia de dos. Si aplicas FFT a una DP, demuestra primero que la transición es una convolución ordinaria; min-plus es otra operación.")
    ],q('Para longitudes 5 y 7, ¿qué longitud potencia de dos evita convolución circular?', ['8','16','4'],1,'El producto tiene 5+7−1=11 coeficientes; la siguiente potencia de dos suficiente es 16.')),

  a('fft-ext','Series formales y operaciones avanzadas con polinomios','Construye inversas, logaritmos y funciones generadoras encima de una multiplicación rápida.',
    ['usaco-adv-fft','usaco-gold-modular'],['Derivar el paso de Newton para invertir una serie','Relacionar operaciones algebraicas con conteos'],[
      s("Trabajar hasta cierto grado","A·B≡1 módulo x^n significa que los primeros n coeficientes del producto son [1,0,…,0]. No necesitas que la serie converja como función real. A tiene inversa si su término constante es invertible en la aritmética elegida.\n\nPara A=1−x, toma B=1+x+x²+x³. Su producto es 1−x⁴, equivalente a uno cuando descartas desde grado cuatro."),
      s("Corrección de Newton","Si B ya aproxima A⁻¹ módulo x^m, calcula B_nuevo=B(2−AB) y descarta desde x^(2m). Escribe AB=1−E: el producto nuevo vale (1−E)(1+E)=1−E². El error que empezaba en grado m pasa a empezar en 2m.\n\nCada iteración duplica la precisión. Con multiplicación O(n log n), la suma de los tamaños duplicados también cuesta O(n log n), usando O(n) memoria con una implementación cuidadosa."),
      s("Otras operaciones de series","Para log A, con A[0]=1, integra A'·A⁻¹ usando (log A)'=A'/A. La exponencial resuelve log B=A mediante Newton y exige A[0]=0. Las raíces cuadradas necesitan una raíz de la constante y condiciones como poder invertir dos.\n\nPuedes reducir división polinómica a inversión tras voltear coeficientes. La evaluación multipunto e interpolación usan árboles de productos y suelen costar O(M(n) log n). Revisa constantes y denominadores antes de aplicar cada operación."),
      s("Funciones generadoras y máscaras","Si puedes usar cualquier cantidad de objetos de tamaño d, 1/(1−x^d) describe sus cantidades. El producto para d=1,…,n cuenta particiones enteras. Para usar cada objeto como mucho una vez, emplea 1+x^d. Compara los primeros coeficientes con una mochila.\n\nSi combinas índices con XOR, usa Walsh–Hadamard: sus mariposas de suma y diferencia trabajan sobre máscaras en O(k·2^k). La normalización inversa debe ser compatible con el módulo.")
    ],q('¿Por qué B(2−AB) duplica precisión al invertir A?', ['Porque duplica todos los coeficientes','Porque el nuevo error es el cuadrado del anterior','Porque elimina los términos pares'],1,'Si AB=1−E, entonces A·B(2−AB)=(1−E)(1+E)=1−E²; el grado mínimo del error se duplica.')),

  a('string-search','Buscar patrones: KMP, Z, palíndromos y Aho–Corasick','Elige una estructura según busques un patrón, muchos patrones o simetrías en una cadena.',
    ['usaco-gold-hashing','usaco-gold-stacks'],['Reutilizar coincidencias sin comparar desde cero','Distinguir búsqueda de patrones y búsqueda de palíndromos'],[
      s("KMP y los bordes","KMP guarda pi[i], la longitud del mayor prefijo propio que también es sufijo de s[0..i]. Tras j coincidencias, si falla la siguiente letra, prueba j=pi[j−1] sin retroceder en el texto.\n\nPara aba, pi=[0,0,1]. Al encontrarlo en ababa, conserva el borde a y detecta otra aparición en el índice dos. Así mantiene el mayor prefijo del patrón que coincide con el final procesado."),
      s("Buscar con KMP o Z","El programa imprime cero y dos al buscar aba en ababa. Exige un patrón no vacío y admite superposiciones.\n\nZ guarda en z[i] cuánto del prefijo coincide desde i. Usa una ventana [l,r) ya comprobada para reutilizar comparaciones. Ambas tablas se calculan en O(n). Para buscar con Z, concatena patrón, un separador ausente de los datos y texto. Elegir un separador que sí aparezca produciría coincidencias incorrectas.", String.raw`#include <iostream>
#include <string>
#include <vector>
using namespace std;
int main(){
  string p="aba",t="ababa";
  vector<int> pi(p.size());
  for(int i=1;i<(int)p.size();++i){
    int j=pi[i-1];
    while(j>0 && p[i]!=p[j]) j=pi[j-1];
    if(p[i]==p[j]) ++j;
    pi[i]=j;
  }
  int j=0;
  for(int i=0;i<(int)t.size();++i){
    while(j>0 && t[i]!=p[j]) j=pi[j-1];
    if(t[i]==p[j]) ++j;
    if(j==(int)p.size()){
      cout<<i-j+1<<'\n'; j=pi[j-1];
    }
  }
}`),
      s("Radios y palíndromos distintos","Manacher guarda radios pares e impares y aprovecha el reflejo dentro del palíndromo que llega más a la derecha. Calcula los radios en O(n). En abacaba, el centro de índice tres tiene radio impar cuatro, contando la letra central.\n\nUn eertree guarda un nodo por palíndromo distinto y enlaces al mayor sufijo palindrómico propio. Tiene O(n) nodos. Sus raíces de longitud cero y −1 simplifican las inserciones y las paridades."),
      s("Buscar varios patrones","Un trie comparte prefijos del diccionario. Aho–Corasick añade enlaces hacia el mayor sufijo que también sea prefijo de algún patrón. Si buscas he y she, encontrar she también debe contar he. Los enlaces de salida permiten reconocer esos sufijos.\n\nCon alfabeto fijo de tamaño σ y transiciones completas, construir cuesta O(L·σ) y enumerar coincidencias O(|texto|+ocurrencias), donde L es la longitud total de patrones. Con transiciones dispersas, el costo depende del contenedor."),
      s("Memoria y tipo de resultado","KMP, Z y Manacher guardan tablas de tamaño O(n). Un trie con arreglos densos puede ocupar mucho si el alfabeto es grande. Además, puede haber una cantidad cuadrática de apariciones: contarlas y listarlas no cuestan lo mismo.\n\nCompara cadenas cortas con búsqueda directa, incluyendo patrones repetidos y contenidos en otros. Define si una posición representa un byte o un carácter; UTF-8 necesita otro tratamiento que las letras de un alfabeto simple.")
    ],q('Después de encontrar aba en ababa, ¿por qué KMP conserva una letra ya coincidente?', ['Para omitir todas las coincidencias solapadas','Porque a es prefijo y sufijo propio de aba','Porque todos los patrones tienen borde uno'],1,'La a final también es el comienzo de aba. Conservar esa coincidencia permite encontrar la segunda aparición, que empieza en la posición 3, o índice 2 si cuentas desde cero.')),

  a('suffix-array','Arreglos de sufijos y prefijos comunes','Ordena todos los sufijos para buscar cadenas y contar subcadenas distintas.',
    ['usaco-gold-hashing','usaco-plat-dc-srq'],['Construir rangos mediante duplicación','Usar LCP para contar y comparar subcadenas'],[
      s("Ordenar los sufijos","Para banana, los sufijos ordenados empiezan en [5,3,1,0,4,2]: a, ana, anana, banana, na, nana. SA guarda esas posiciones; copiar todos los sufijos ocuparía memoria cuadrática.\n\nLos que empiezan con el mismo patrón quedan juntos. Dos búsquedas binarias delimitan sus apariciones. Si cada comparación recorre el patrón, la búsqueda cuesta O(|patrón| log n)."),
      s("Duplicar los bloques comparados","Ordena primero por letra y asigna rangos iguales a letras iguales. En cada ronda, describe un bloque mediante los rangos de sus dos mitades; usa un centinela menor para la parte que salga del texto. Ordenar esos pares permite duplicar la longitud conocida.\n\nTras O(log n) rondas distingues todos los sufijos. Con sort, construir cuesta O(n log² n); con radix o counting sort por rangos, O(n log n)."),
      s("Usar el prefijo común","LCP[i] mide la coincidencia entre SA[i−1] y SA[i]. En banana, los valores vecinos son [1,3,0,0,2]. Hay 21 intervalos por posición. Restas su suma, seis, y quedan quince subcadenas distintas.\n\nCada sufijo aporta sus prefijos salvo los ya presentes en el anterior. Kasai calcula LCP en O(n), reutilizando que avanzar una posición reduce una coincidencia conocida como mucho en una letra."),
      s("Consultas y separadores","El LCP de dos sufijos es el mínimo de los LCP consecutivos entre sus rangos. Una estructura RMQ acelera esas consultas. Si agregas un terminador, debe ser único y quedar excluido del conteo original.\n\nPrueba aaaa y textos de letras distintas. Compara SA con ordenar sufijos directamente en entradas pequeñas. Para varios textos, usa separadores adecuados y evita contar fragmentos que crucen sus fronteras.")
    ],q('¿Cuántas subcadenas distintas tiene banana según sus LCP?', ['21','15','7'],1,'Hay 6·7/2=21 subcadenas por posición. Los LCP consecutivos son 1, 3, 0, 0 y 2: suman 6. Quedan 21−6=15 subcadenas distintas.')),

  a('string-suffix','Autómatas y árboles de sufijos','Representa todas las subcadenas de un texto con una estructura de tamaño lineal.',
    ['usaco-adv-suffix-array','usaco-adv-string-search'],['Interpretar estados y enlaces de un autómata de sufijos','Comparar autómata, árbol y arreglo de sufijos'],[
      s("Subcadenas con los mismos finales","Un autómata de sufijos agrupa subcadenas que terminan en las mismas posiciones. En cada estado v, len[v] es la longitud máxima y link[v] apunta al mayor sufijo propio cuyo conjunto de finales cambia.\n\nEl estado representa longitudes desde len[link[v]]+1 hasta len[v]. Cada camino desde la raíz etiqueta una subcadena distinta. Esa interpretación permite derivar consultas y conteos."),
      s("Extender y separar clases","Al agregar una letra, crea el estado del nuevo prefijo completo y añade transiciones faltantes siguiendo enlaces de sufijo. Si encuentras una transición cuya longitud no encaja, crea un clon con sus transiciones y enlace, pero con longitud menor. Redirige las transiciones correspondientes y ajusta los enlaces.\n\nEl clon separa clases que dejaron de compartir finales. No agrega una aparición nueva; su contador empieza en cero."),
      s("Contar en aba","Las subcadenas distintas de aba son a,b,ab,ba,aba. Puedes contarlas sumando len[v]−len[link[v]] sobre los estados distintos de la raíz.\n\nPara frecuencias, asigna uno a los estados creados por cada prefijo y propaga de mayor a menor len hacia link. Obtienes dos apariciones de a y una de ab. Para comparar con otro texto, recórrelo sobre el autómata y sigue enlaces cuando falle una transición."),
      s("Árboles comprimidos","Un árbol de sufijos comprime los caminos de un trie de todos los sufijos. Sus aristas guardan intervalos del texto. Ukkonen lo construye en línea con un punto activo y enlaces; también puedes construirlo desde SA y LCP.\n\nCon alfabeto fijo, autómata y árbol admiten construcción y memoria O(n); mapas ordenados añaden factores logarítmicos. Compara conteos con un conjunto explícito de subcadenas pequeñas y usa separadores al combinar textos.")
    ],q('¿Cuántas longitudes de subcadena representa un estado v no inicial?', ['len[v]','len[v]−len[link[v]]','len[link[v]]+1'],1,'Las longitudes forman el intervalo entero desde len[link[v]]+1 hasta len[v], cuya cantidad es la diferencia.')),

  a('extend-euclid','Euclides extendido, ecuaciones e inversos','Encuentra coeficientes de Bézout y decide cuándo una ecuación entera tiene solución.',
    ['usaco-gold-divisibility','usaco-gold-modular'],['Obtener x e y con ax+by=gcd(a,b)','Resolver congruencias sin suponer módulo primo'],[
      s("Encontrar coeficientes de Bézout","Euclides calcula gcd(a,b) reemplazando (a,b) por (b,a mod b). La versión extendida también encuentra x,y tales que ax+by=gcd(a,b). Puedes comprobarlos sustituyendo en la igualdad.\n\nPara 30 y 18, sirven x=−1,y=2: −30+36=6. Aunque las entradas sean positivas, los coeficientes pueden ser negativos. Guárdalos en tipos con signo."),
      s("Volver de la llamada recursiva","Supón que ya tienes b·x1+(a mod b)·y1=g. Sustituye a mod b por a−floor(a/b)·b. Queda a·y1+b·(x1−floor(a/b)·y1)=g. Por tanto, x=y1 e y=x1−(a/b)·y1.\n\nSi b=0 y a>0, devuelve g=a,x=1,y=0. El programa usa entradas positivas moderadas. Para valores cercanos al límite, revisa los productos intermedios y normaliza los signos.", String.raw`#include <iostream>
#include <tuple>
using namespace std;
tuple<long long,long long,long long> egcd(long long a,long long b){
  if(b==0) return {a,1,0};
  auto [g,x1,y1]=egcd(b,a%b);
  return {g,y1,x1-(a/b)*y1};
}
int main(){
  auto [g,x,y]=egcd(30,18);
  cout<<g<<' '<<x<<' '<<y<<'\n';
  cout<<30*x+18*y<<'\n';
}`),
      s("Resolver ecuaciones e inversos","ax+by=c tiene solución entera si y solo si g=gcd(a,b) divide c. Multiplica los coeficientes de Bézout por c/g para obtener (x0,y0). Todas las soluciones son x=x0+t·b/g, y=y0−t·a/g.\n\nSi gcd(a,m)=1, el coeficiente de a da su inverso módulo m; normalízalo a [0,m). Como 3·4−11=1, cuatro es inverso de tres módulo once. m no necesita ser primo."),
      s("Combinar congruencias","Las condiciones x≡r1 mod m1 y x≡r2 mod m2 son compatibles si gcd(m1,m2) divide r2−r1. Euclides extendido obtiene el desplazamiento y el nuevo periodo lcm(m1,m2).\n\nPara entradas positivas hace O(log min(a,b)) divisiones; la recursión usa esa profundidad. Si exiges x,y≥0, restringe el intervalo de t. Con negativos, la división de C++ trunca hacia cero y puede diferir del piso. Comprueba la respuesta en la ecuación original.")
    ],q('¿Tiene solución entera 6x+10y=7?', ['Sí, por Bézout','No, porque 2 no divide 7','Solo con x negativo'],1,'gcd(6,10)=2 y cualquier combinación entera es par; siete no es múltiplo del máximo común divisor.')),

  a('catalan','Números de Catalan y estructuras balanceadas','Cuenta paréntesis, árboles y caminos mediante una descomposición única.',
    ['usaco-gold-combo','usaco-gold-intro-dp'],['Derivar la recurrencia de Catalan','Distinguir conteo exacto y modular'],[
      s("Problemas con la misma descomposición","Los números de Catalan cuentan paréntesis balanceados con n parejas, árboles binarios ordenados con n nodos internos de exactamente dos hijos y triangulaciones de un polígono convexo de n+2 vértices. Todos admiten una separación recursiva parecida.\n\nAntes de aplicar la cuenta, identifica la correspondencia. Cambiar el orden de los hijos, qué llamas tamaño o alguna restricción puede cambiar el resultado."),
      s("Separar la primera pareja","Una secuencia no vacía se escribe de forma única como (A)B. Si A contiene i parejas, B tiene n−1−i. Puedes elegir ambas partes independientemente, así que C[n]=Σ C[i]·C[n−1−i], para i de cero a n−1.\n\nUsa C[0]=1 para permitir partes vacías. Obtienes C[1]=1, C[2]=2 y C[3]=2+1+2=5. El programa calcula directamente esa recurrencia.", String.raw`#include <iostream>
#include <vector>
using namespace std;
int main(){
  int n=10;
  vector<long long> c(n+1);
  c[0]=1;
  for(int size=1;size<=n;++size)
    for(int left=0;left<size;++left)
      c[size]+=c[left]*c[size-1-left];
  for(int i=0;i<=n;++i) cout<<c[i]<<(i==n?'\n':' ');
}`),
      s("Contar caminos válidos","Representa abrir como subir y cerrar como bajar. De los binom(2n,n) caminos con igual cantidad de pasos, algunos bajan de cero. Reflejar su tramo inicial permite contar binom(2n,n+1) caminos inválidos.\n\nPor eso C[n]=binom(2n,n)−binom(2n,n+1)=binom(2n,n)/(n+1). Para n=3, 20−15=5. Tener la misma cantidad total de aperturas y cierres no basta: cada prefijo debe mantener altura no negativa."),
      s("Costo y divisiones modulares","La recurrencia cuesta O(n²) y ocupa O(n). Con factoriales e inversos módulo un primo adecuado puedes preparar la fórmula en O(n), pero debes comprobar que los denominadores sean invertibles. Si el módulo divide n+1, no puedes usar su inverso.\n\nLos valores exactos desbordan pronto; el ejemplo limita n a diez. Genera todas las secuencias para n≤5 y compara. La misma separación en dos partes explica el conteo de árboles ordenados.")
    ],q('¿Por qué C[0]=1 en la recurrencia?', ['Porque existen cero estructuras vacías','Porque hay una elección de estructura vacía','Porque mejora la complejidad'],1,'La estructura vacía es una posibilidad válida y debe aportar un factor uno cuando una de las dos partes está vacía.')),

  a('xor-basis','Bases XOR y álgebra sobre bits','Resume todos los XOR de subconjuntos mediante vectores linealmente independientes.',
    ['usaco-silver-intro-bitwise','usaco-gold-dp-bitmasks'],['Insertar vectores eliminando su bit principal','Consultar pertenencia y máximo XOR'],[
      s("Interpretar un número como vector","Cada bit es una coordenada que vale cero o uno. Sumar coordenadas módulo dos equivale a XOR: uno más uno vuelve a cero. Los XOR de subconjuntos forman un espacio que puedes representar con una base pequeña.\n\nGuarda como mucho un vector por bit principal. Un trie organiza números individuales; esta base representa combinaciones de varios números."),
      s("Cancelar bits al insertar","Recorre x de bits altos a bajos. Si el bit b está encendido y ya tienes basis[b], haz x XOR basis[b]. Apagas b sin crear bits mayores. Si no hay pivote, guarda x ahí. Si llegas a cero, el número dependía de los anteriores.\n\nCon 3=011 y 5=101 guardas dos vectores. Al insertar 6=110, 6 XOR 5 XOR 3=0: ya podías formarlo."),
      s("Consultar y maximizar","Para saber si puedes formar un valor, redúcelo con los pivotes. Si llegas a cero, sí. Para maximizar, empieza en cero y aplica cada pivote de mayor a menor solo cuando aumente la respuesta. Los pivotes posteriores no alteran los bits superiores ya decididos.\n\nEl programa usa enteros sin signo de 64 bits. Para {3,5,6}, los resultados posibles son 0,3,5,6 y el máximo es seis.", String.raw`#include <iostream>
#include <array>
#include <cstdint>
using namespace std;
int main(){
  array<uint64_t,64> basis{};
  for(uint64_t x:{uint64_t(3),uint64_t(5),uint64_t(6)}){
    for(int bit=63;bit>=0;--bit){
      if(((x>>bit)&1)==0) continue;
      if(basis[bit]) x^=basis[bit];
      else {basis[bit]=x;break;}
    }
  }
  uint64_t answer=0;
  for(int bit=63;bit>=0;--bit)
    if((answer^basis[bit])>answer) answer^=basis[bit];
  cout<<answer<<'\n';
}`),
      s("Rango y costo","Construir con n valores de B bits cuesta O(nB). Una consulta cuesta O(B) y la base ocupa O(B). Si el rango es r, hay 2^r resultados distintos; cada uno tiene 2^(n−r) subconjuntos de índices que lo producen. Esa cuenta puede necesitar enteros grandes o módulo.\n\nLa base sencilla no admite borrados arbitrarios ni cualquier restricción de posiciones. Compara arreglos cortos con enumeración, incluyendo ceros y repetidos.")
    ],q('Si tres números tienen rango XOR dos, ¿cuántos XOR distintos generan?', ['3','4','8'],1,'Un espacio de dimensión dos sobre el campo de dos elementos tiene 2²=4 vectores distintos.')),

  a('fracturing-search','Fracturing search: enumerar las mejores soluciones','Parte un espacio enorme en regiones disjuntas y visita primero la mejor candidata de cada región.',
    ['usaco-silver-priority-queues','usaco-gold-mst'],['Diseñar un árbol implícito sin duplicados','Separar costo de enumeración y costo de optimización local'],[
      s("Entregar las primeras K soluciones","Supón que puedes encontrar fácilmente el objeto más barato, pero quieres los K primeros de un conjunto enorme. Organízalos como un árbol implícito: la raíz es el mínimo y cada hijo cuesta al menos lo mismo que su padre.\n\nGuarda la raíz en una cola de prioridad. Extrae el menor candidato y agrega sus hijos. Cada objeto aún oculto queda debajo de uno pendiente y no puede mejorar su costo."),
      s("Evitar regiones superpuestas","Los hijos deben cubrir las soluciones restantes sin repetirlas. Para árboles generadores, ordena las aristas e1,…,er del mejor árbol. La región i obliga a incluir e1,…,e(i−1) y prohíbe ei.\n\nOtro árbol tiene una primera arista de esa lista que omite, así que pertenece a una sola región. Calcula su mínimo con las restricciones acumuladas. Prohibir una arista diferente en cada hijo sin fijar las anteriores produciría duplicados."),
      s("Sumas de dos listas","Con A=[1,4] y B=[2,5], cada par (i,j) cuesta A[i]+B[j]. Empieza en (0,0). Sucesores: (i,j+1), si existe, y solo cuando j=0, (i+1,0).\n\nCada par tiene un único padre y sus valores no disminuyen, porque las listas están ordenadas. La cola devuelve 3,6,6,9. Los dos seises vienen de pares distintos; eliminarlos como duplicados cambiaría la pregunta."),
      s("Contar el trabajo por región","Si generas como mucho D hijos por objeto en O(1) cada uno, obtener K objetos cuesta O(KD log(KD)) y ocupa O(KD). Si calcular el mínimo de cada región cuesta T, añade O(KDT).\n\nOtra posibilidad es buscar un umbral y contar hasta K nodos permitidos, cuando el problema lo admita. Comprueba todos los pares de listas pequeñas; para árboles generadores pequeños, verifica que cada partición incluya cada árbol exactamente una vez.")
    ],q('¿Qué condición evita duplicar soluciones al dividir una región?', ['Que todas las regiones tengan el mismo tamaño','Que los hijos formen subespacios disjuntos','Que todos los valores sean distintos'],1,'La disyunción da un único lugar a cada objeto; valores iguales pueden pertenecer legítimamente a soluciones diferentes.')),

  a('game-theory','Teoría de juegos: estados ganadores, Nim y Grundy','Resuelve juegos imparciales finitos separando estrategia, estados y combinación de componentes.',
    ['usaco-gold-intro-dp','usaco-silver-intro-bitwise'],['Calcular estados ganadores y números de Grundy','Verificar las hipótesis para combinar juegos con XOR'],[
      s("Estados ganadores y perdedores","Considera un juego finito sin azar ni información oculta. Ambos jugadores tienen las mismas jugadas disponibles y pierde quien no puede mover.\n\nEn su grafo de estados sin ciclos, una posición gana si permite ir a una perdedora. Pierde si todas sus jugadas van a ganadoras; un estado sin jugadas también pierde. Si cambias la condición de victoria o permites ciclos indefinidos, debes revisar este modelo."),
      s("Calcular Grundy","Define g(s) como el mex de los valores de sus sucesores. Mex es el menor entero no negativo ausente. Un estado terminal vale cero.\n\nSi quitas una o dos piedras, los tamaños 0,1,2,3,4 tienen valores 0,1,2,0,1. Desde tres llegas a valores dos y uno, así que su mex es cero: pierdes con juego óptimo. En este modelo, g≠0 identifica los estados ganadores."),
      s("Combinar juegos independientes","Si cada turno modifica un solo componente y deja intactas las reglas de los demás, combina sus Grundy con XOR. En Nim puedes quitar cualquier cantidad positiva de una pila, por lo que su Grundy es su tamaño.\n\nPara [3,4,5], el XOR es dos. Reduce la pila de tres a uno y dejas 1 XOR 4 XOR 5=0. La estrategia ganadora devuelve un XOR cero al rival después de cada respuesta."),
      s("Costo y variantes","En un DAG explícito, marcar para cada mex hasta el grado de salida permite calcular los Grundy en O(V+E), con O(V+E) memoria. En un juego implícito, cuenta sus estados y movimientos.\n\nNo uses XOR si una jugada cambia varios componentes sin demostrar que se separan. Nim misère necesita excepciones porque pierde quien toma la última piedra. Si observas períodos al calcular valores, demuéstralos antes de extrapolarlos indefinidamente.")
    ],q('Un estado tiene sucesores con Grundy {0,1,3}. ¿Cuál es su Grundy?', ['0','2','4'],1,'mex es el menor entero no negativo ausente: están cero y uno, pero falta dos.')),

  a('prefix-sums-nt-1','Sumas aritméticas I: cocientes y convolución de Dirichlet','Agrupa divisiones enteras repetidas y convierte identidades de divisores en prefijos rápidos.',
    ['usaco-gold-divisibility','usaco-gold-modular'],['Enumerar intervalos con el mismo cociente','Derivar sumas de divisores y una recurrencia para totientes'],[
      s("Saltar cocientes repetidos","floor(N/i) solo toma O(√N) valores distintos. Hasta √N hay pocos índices; después, los cocientes son menores que √N. Si un bloque comienza en l con q=floor(N/l), termina en r=floor(N/q). Continúa en r+1.\n\nPara N=10, los bloques son [1,1],[2,2],[3,3],[4,5],[6,10], con cocientes 10,5,3,2,1. Puedes procesar cada grupo de una vez."),
      s("Contar cada divisor en sus múltiplos","σ(k) suma los divisores de k. Para sumar todos los σ(k) hasta N, un divisor d aparece floor(N/d) veces. Por eso S(N)=Σ d·floor(N/d). Un bloque [l,r] aporta q·(l+r)(r−l+1)/2.\n\nCon N=5, sumas 1+3+4+7+6=21; contando por divisor también da 5+4+3+4+5=21. El programa usa N=10 y devuelve 87. Divide primero el factor par entre dos para reducir productos intermedios.", String.raw`#include <iostream>
using namespace std;
int main(){
  long long n=10,answer=0;
  for(long long l=1;l<=n;){
    long long quotient=n/l,r=n/quotient;
    long long x=l+r,y=r-l+1;
    if(x%2==0) x/=2; else y/=2;
    answer+=quotient*x*y;
    l=r+1;
  }
  cout<<answer<<'\n';
}`),
      s("Convolución de Dirichlet y totientes","Define (f*g)(n)=Σ(d|n)f(d)g(n/d). Una función multiplicativa cumple f(1)=1 y f(ab)=f(a)f(b) para a,b coprimos; conserva esa condición. Möbius es la inversa de la función constante uno bajo esta convolución.\n\nSea Φ(x)=Σ(i≤x)φ(i). Sumar la identidad Σ(d|n)φ(d)=n hasta N da Σ(k=1…N)Φ(floor(N/k))=N(N+1)/2. Separa k=1, agrupa los demás por cociente y memoriza los resultados para calcular Φ(N)."),
      s("Costo de la recursión","La suma de divisores por bloques cuesta O(√N) y usa O(1) memoria. La recurrencia de totientes calcula también otros argumentos: sin criba inicial, una cota conservadora es O(N^(3/4)) tiempo y O(√N) resultados para una consulta, con acceso eficiente a los cocientes. Precalcular prefijos pequeños mejora el equilibrio.\n\nCompara con una criba hasta mil. Con módulos compuestos, revisa si las divisiones o inversos necesarios existen.")
    ],q('Para N=20 y l=6, ¿hasta qué r se mantiene floor(N/i)=3?', ['6','7','8'],0,'q=20/6=3 y r=floor(20/3)=6; en i=7 el cociente ya baja a dos.')),

  a('prefix-sums-nt-2','Sumas aritméticas II: contar primos sin llegar a N','Combina una criba dinámica con los O(√N) cocientes necesarios para calcular π(N).',
    ['usaco-adv-prefix-sums-nt-1'],['Mantener conteos filtrados por primos pequeños','Respetar el orden de actualización en una criba comprimida'],[
      s("Guardar solo los límites necesarios","π(N) es la cantidad de primos hasta N. Si no cabe una marca por entero, conserva los valores floor(N/i): solo hay O(√N).\n\nDividir uno de ellos vuelve a producir un valor del mismo conjunto: floor(floor(N/i)/p)=floor(N/(ip)). Así puedes consultar todos los argumentos de la recurrencia sin construir un arreglo de N posiciones."),
      s("Filtrar con cada primo","Empieza G(v)=v−1, que cuenta de dos a v. Para cada primo p≤√N y cada v≥p², resta G(floor(v/p))−G(p−1). Esa cantidad corresponde a los nuevos compuestos cuyo menor factor primo es p.\n\nUsa los valores anteriores a esta etapa. Recorre v de mayor a menor: el argumento floor(v/p) es más pequeño y todavía no habrá cambiado. Restar G(p−1) evita eliminar el primo y productos ya filtrados."),
      s("Contar los primos hasta diez","Guarda v=[10,5,3,2,1] y G=[9,4,2,1,0]. Con p=2, G(10) pierde G(5)−G(1)=4 y queda cinco. G(5) pierde G(2)−G(1)=1 y queda tres.\n\nCon p=3, solo diez cumple v≥9. Pierde G(3)−G(2)=1 y queda cuatro: 2,3,5,7. Puedes detectar p primo cuando G(p)>G(p−1) antes de procesarlo."),
      s("Costo y límites numéricos","Visitar solo v≥p² da una cota segura O(N^(3/4)) y O(√N) memoria, con índices en arreglos que resuelvan accesos en O(1). Variantes con cortes o Fenwick requieren otro análisis.\n\nCompara todos los N pequeños con Eratóstenes. Calcula p*p en un tipo ancho y ajusta la raíz cuadrada si la obtuviste con punto flotante. Los cuadrados exactos permiten comprobar esos límites.")
    ],q('¿Por qué se recorren los valores v de mayor a menor al procesar p?', ['Para obtener primos ordenados','Para que G(v/p) siga siendo de la etapa anterior','Porque G es decreciente'],1,'La recurrencia elimina múltiplos usando los conteos anteriores a p; actualizar primero los valores menores los modificaría demasiado pronto.')),

  a('matroid','Matroides: cuándo un algoritmo voraz tiene garantía','Reconoce independencia e intercambio detrás de Kruskal, bases lineales y cupos por categoría.',
    ['usaco-gold-mst','usaco-adv-xor-basis'],['Verificar los tres axiomas de un matroide','Justificar selección voraz mediante intercambio'],[
      s("Tres reglas para independencia","Un matroide define qué subconjuntos de un conjunto finito E son independientes. Exige que el vacío lo sea y que quitar elementos conserve independencia.\n\nAdemás, si A y B son independientes y |A|<|B|, algún elemento de B fuera de A puede agregarse a A sin perder independencia. Esta regla es intercambio. Las dos primeras por sí solas no garantizan que elegir los elementos más baratos funcione."),
      s("Bosques, vectores y cupos","En el matroide gráfico, los elementos son aristas y los independientes son bosques: agregas una arista si no cierra ciclo. En el lineal, eliges vectores independientes.\n\nEn el de partición, cada categoría tiene un cupo. Elegir como mucho dos problemas de grafos y uno de geometría es un ejemplo. El uniforme permite cualquier selección con tamaño como mucho r. Todos cumplen las mismas tres reglas."),
      s("Encontrar una base mínima","Una base es un independiente que ya no puedes ampliar. Intercambio obliga a que todas las bases tengan igual tamaño. Para encontrar la de menor peso, ordena por peso creciente y acepta cada elemento si conserva independencia.\n\nUn intercambio permite hacer coincidir una base óptima con cada elección voraz sin aumentar su costo. Kruskal es este procedimiento en el matroide gráfico; el DSU comprueba si agregar la arista forma un ciclo."),
      s("Costo y objetivo","Con n elementos y costo T por prueba de independencia, el esquema cuesta O(n log n+nT). El oráculo puede aprovechar una estructura incremental. Si buscas máximo peso sin tamaño obligatorio, omite los negativos; completar una base sería otro objetivo.\n\nComprueba intercambio para cupos. Después revisa conjuntos de vértices sin vecinos: en general no forman un matroide. Un independiente maximal pequeño que no pueda ampliarse con otro mayor demuestra la falla.")
    ],q('¿Qué axioma falta si una familia contiene el vacío y es cerrada por subconjuntos?', ['Orden por peso','Intercambio entre independientes de tamaños distintos','Conectividad'],1,'La heredabilidad no basta; el intercambio permite ampliar el conjunto menor usando algún elemento del mayor.')),

  a('matroid-isect','Intersección de matroides','Encuentra el mayor conjunto que respeta dos tipos distintos de independencia.',
    ['usaco-adv-matroid','usaco-adv-max-flow'],['Construir un grafo de intercambio dirigido','Aumentar la solución con un camino más corto'],[
      s("Cumplir dos independencias","Quieres aristas que formen un bosque y respeten cupos por color. Son un matroide gráfico y uno de partición sobre el mismo conjunto E.\n\nSu intersección no tiene por qué ser un matroide, así que aceptar elementos vorazmente pierde la garantía anterior. El algoritmo de intersección busca una selección común del mayor tamaño mediante cadenas de intercambios."),
      s("Fuentes, destinos e intercambios","Mantén S independiente en ambos matroides. Para x fuera e y dentro, agrega y→x si S−y+x es independiente en M1; agrega x→y si lo es en M2.\n\nSon fuentes los x que puedes añadir directamente en M1, y destinos los que puedes añadir en M2. Busca con BFS el camino más corto entre ambos conjuntos. Alterna pertenencia a lo largo del camino: agregas un elemento más de los que quitas."),
      s("Aumentar un emparejamiento","No repetir vértice izquierdo ni derecho define dos matroides de partición. Con aristas a–1,a–2,b–1, la selección {a–1} no permite agregar directamente otra válida en ambos lados.\n\nEl camino b–1,a–1,a–2 quita a–1 y agrega las otras dos. La selección crece a dos. El teorema de intersección garantiza que un camino aumentante mínimo conserva las independencias y que, si ya no existe, la cantidad es máxima."),
      s("Costo y variantes","Con n=|E| y costo T por consulta de independencia, reconstruir el grafo en hasta n aumentos da O(n³T+n³) tiempo y O(n²) memoria. Usar el rango o estructuras especiales puede mejorarlo.\n\nEl dual tiene como bases los complementos de las bases originales. Contraer un independiente A fija su elección: B es válido si A unido con B lo era. La versión ponderada requiere otro algoritmo; BFS resuelve aquí cardinalidad.")
    ],q('¿Qué ocurre al alternar pertenencia sobre un camino aumentante?', ['Se agregan exactamente dos elementos netos','Se agrega un elemento neto manteniendo ambas independencias','Se pierde una de las restricciones'],1,'El camino empieza y termina fuera de S y alterna dentro/fuera, por lo que incluye un elemento externo más que internos.')),

  a('random','Algoritmos aleatorizados y probabilidad de error','Calcula la probabilidad de fallo de un muestreo y comprueba los candidatos encontrados.',
    ['usaco-gold-hashing','usaco-gold-combo'],['Separar tiempo aleatorio de respuesta aleatoria','Acotar fallos de muestreo y verificar candidatos'],[
      s("Respuesta aleatoria o tiempo aleatorio","En Las Vegas, la respuesta es correcta y el tiempo depende del azar, como en un treap con prioridades aleatorias. En Monte Carlo, el trabajo está controlado y existe una probabilidad de error.\n\nAntes de usar muestreo, demuestra por qué puede encontrar una respuesta y cuánto riesgo queda. Esa cuenta debe cubrir todas las consultas, no solo una ejecución favorable."),
      s("Probabilidad de no encontrar un testigo","Si al menos una fracción p de los elementos revela un candidato óptimo, k muestras uniformes e independientes con reemplazo lo omiten con probabilidad (1−p)^k. Para p≥1/2 y k=30, la cota es 2^−30.\n\nCuando puedas, comprueba el candidato contra todos los datos. Eso evita aceptar uno inválido, pero todavía podrías no haber encontrado el mejor. Distingue ambos tipos de fallo."),
      s("Muestrear una frecuencia alta","Buscas un valor que aparezca en al menos un tercio del arreglo. Cada muestra lo encuentra con probabilidad como mínimo 1/3. Veinte muestras lo omiten con probabilidad como mucho (2/3)^20<0.00031.\n\nCuenta exactamente las apariciones de cada valor distinto muestreado antes de reportarlo. Este problema también admite algoritmos deterministas eficientes; el ejemplo sirve para entender qué demuestra el cálculo probabilístico."),
      s("Riesgo total y costo","Si haces Q consultas de riesgo como mucho ε cada una, la probabilidad de algún fallo es como mucho Qε, incluso sin independencia entre consultas. Muestrea índices con uniform_int_distribution y guarda la semilla para reproducir pruebas.\n\nVerificar k candidatos directamente cuesta O(kn) y O(k) memoria; una tabla de frecuencias cambia el balance. Compara tasas observadas con la fórmula, recordando que medir casos no demuestra la garantía.")
    ],q('Si cada muestra independiente tiene probabilidad p de ser testigo, ¿cuál es la probabilidad de fallar k veces?', ['p·k','(1−p)^k','1−p^k'],1,'Fallar una vez tiene probabilidad 1−p y la independencia permite multiplicar ese factor k veces.')),

  a('interactive','Problemas interactivos y de comunicación','Diseña preguntas informativas y protocolos que no se bloqueen al conversar con el juez.',
    ['usaco-silver-binary-search','usaco-silver-intro-bitwise','usaco-general-input-output'],['Separar presupuesto de consultas y tiempo de cómputo','Demostrar un protocolo de información limitada'],[
      s("Respetar el protocolo","Tu programa envía una consulta, vacía la salida y lee la respuesta del juez. En C++, endl vacía el búfer; con un salto de línea normal, usa flush si hace falta. El enunciado fija formato, rangos, límite de consultas y respuestas de error.\n\nNo mezcles mensajes de depuración con la salida del protocolo. La respuesta final suele tener un formato diferente de las preguntas."),
      s("Información de una pregunta","Con q preguntas de sí o no distingues como mucho 2^q secuencias de respuestas. Para identificar cualquiera de N candidatos necesitas al menos ceil(log2 N) preguntas en el peor caso. No hace falta suponerlos equiprobables.\n\nPuedes alcanzar la cota si las preguntas permitidas separan bien el conjunto. Para un número de uno a ocho, pregunta si es como mucho cuatro y continúa por mitades: tres consultas bastan."),
      s("Comunicar un objetivo con XOR","Tienes 2^k monedas etiquetadas de cero a 2^k−1. Una persona conoce el objetivo t y puede voltear exactamente una moneda; otra solo verá el tablero final. Acuerdan calcular c como XOR de las etiquetas cara arriba.\n\nVoltea j=c XOR t. El XOR nuevo es c XOR j=t, que permite recuperar el objetivo. Si j=0, volteas la moneda cero: el XOR ya era t y permanece igual."),
      s("Simular la estrategia","Construye un juez local que responda, cuente consultas y rechace formatos inválidos. Prueba todos los objetivos pequeños y los extremos grandes. Mide consultas por separado del tiempo: ahorrar comunicación puede requerir más cálculo.\n\nLa búsqueda binaria usa O(log N) preguntas y O(1) memoria. En problemas con dos programas, define qué sabe cada uno y qué bits puede enviar. Una variable global o archivo local no comunica información entre ellos.")
    ],q('En el protocolo de monedas, ¿qué etiqueta debe voltearse si c=6 y t=3?', ['3','5','9'],1,'6 XOR 3=5; el nuevo XOR será 6 XOR 5=3, que es el objetivo.')),

  a('vectorization','Vectorización en C++ y rendimiento medido','Comprende SIMD, dependencias de bucles y las condiciones reales para optimizar sin cambiar resultados.',
    ['usaco-bronze-time-comp','usaco-plat-bitsets','usaco-general-cpp-command'],['Reconocer iteraciones que pueden procesarse juntas','Medir optimizaciones y revisar compatibilidad del compilador'],[
      s("Una operación sobre varios datos","SIMD permite aplicar una instrucción a varios datos. Sumar dos arreglos elemento a elemento es un candidato: cada resultado se calcula independientemente. En a[i]+=a[i−1], en cambio, necesitas el resultado anterior.\n\nLa vectorización puede mejorar una constante, pero no cambia O(n²) por O(n log n). Primero elige una complejidad adecuada; después revisa operaciones y accesos a memoria."),
      s("Qué puede demostrar el compilador","Los arreglos contiguos, ciclos simples y ausencia de solapamientos ambiguos facilitan probar independencia. Los reportes de GCC o Clang indican qué ciclos vectorizaron; sus decisiones dependen de la versión y la plataforma.\n\nTambién importa la CPU. Un ejecutable con AVX2 puede no funcionar donde falte ese soporte. Las directivas particulares de GCC no forman una interfaz portable de C++17."),
      s("Un ejemplo portable","El programa suma dos arreglos sin signo y luego imprime una suma de comprobación. Obtiene c=[6,8,10,12] y total 36. Imprimir el resultado evita que el compilador elimine todo el trabajo como innecesario.\n\nPara experimentar, aumenta el tamaño y compara configuraciones de optimización con sus reportes. Un tiempo menor no demuestra por sí solo SIMD: pueden intervenir otras transformaciones.", String.raw`#include <iostream>
#include <vector>
#include <cstdint>
using namespace std;
int main(){
  vector<uint32_t> a={1,2,3,4},b={5,6,7,8},c(a.size());
  for(size_t i=0;i<a.size();++i) c[i]=a[i]+b[i];
  uint64_t checksum=0;
  for(uint32_t value:c) checksum+=value;
  cout<<checksum<<'\n';
}`),
      s("Medir sin cambiar el resultado","El programa sigue usando O(n) tiempo y memoria. El límite puede ser el ancho de banda de memoria. Repite mediciones con tamaños representativos y separa entrada, cálculo y salida.\n\nLas opciones de matemáticas rápidas pueden reordenar decimales y cambiar redondeos, NaN o ceros con signo. Desbordar enteros con signo sigue siendo comportamiento indefinido. Compara resultados exactos o con una tolerancia justificada y conserva una versión portable de referencia.")
    ],q('¿Qué bucle es candidato directo a vectorización por independencia?', ['c[i]=a[i]+b[i]','a[i]+=a[i−1]','Procesar el siguiente nodo según el anterior'],0,'Cada c[i] depende de posiciones independientes de entrada; no necesita el resultado calculado en la iteración anterior.')),
];
